insert into public.regions (id, name, position, created_at, updated_at, code, capital, description, image_url, color) values
  ('greater-accra', 'Greater Accra', 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'GA', 'Accra', 'The capital region of Ghana, home to the bustling city of Accra, historic landmarks, beautiful beaches, and vibrant nightlife. It is the economic and political hub of the country.', 'https://images.unsplash.com/photo-1589825743636-23a879d4b8e2?w=800&q=80', 'bg-blue-600'),
  ('ashanti', 'Ashanti', 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'AH', 'Kumasi', 'The cultural heartland of Ghana, known for its rich Ashanti heritage, the Golden Stool, Kente cloth weaving, and the magnificent Manhyia Palace. Kumasi is Ghana''s second-largest city.', 'https://images.unsplash.com/photo-1565373677928-80cf5b789d2e?w=800&q=80', 'bg-yellow-600'),
  ('central', 'Central', 2, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'CP', 'Cape Coast', 'Home to Cape Coast and Elmina castles, powerful reminders of Ghana''s slave trade history, as well as the spectacular Kakum National Park with its canopy walkway.', 'https://images.unsplash.com/photo-1575986767340-5d17ae767ab0?w=800&q=80', 'bg-green-700'),
  ('western', 'Western', 3, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'WN', 'Sekondi-Takoradi', 'Known for its lush rainforests, scenic beaches, and the unique floating village of Nzulezu. The region is also rich in natural resources including oil and cocoa.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'bg-emerald-700'),
  ('eastern', 'Eastern', 4, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'EP', 'Koforidua', 'A region of scenic landscapes featuring the Aburi Botanical Gardens, beautiful waterfalls, and the Akwapim Hills. The area is known for its pleasant climate and stunning views.', 'https://images.unsplash.com/photo-1598512752271-33f913a5af13?w=800&q=80', 'bg-lime-700'),
  ('volta', 'Volta', 5, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'VR', 'Ho', 'Home to the magnificent Wli Waterfalls — the highest in West Africa — as well as Lake Volta, one of the world''s largest man-made lakes. The region boasts dramatic mountain scenery.', 'https://images.unsplash.com/photo-1564419320461-6870880221ad?w=800&q=80', 'bg-teal-600'),
  ('northern', 'Northern', 6, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'NR', 'Tamale', 'Gateway to northern Ghana, featuring unique traditional architecture, vibrant markets, Larabanga Mosque, and proximity to Mole National Park. Rich in Islamic heritage and culture.', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=800&q=80', 'bg-orange-700'),
  ('upper-east', 'Upper East', 7, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'UE', 'Bolgatanga', 'Known for Paga''s sacred crocodile pond, the Bolgatanga cultural market, and unique Frafra pottery. The region shares borders with Burkina Faso and Togo.', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=800&q=80', 'bg-red-700'),
  ('upper-west', 'Upper West', 8, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'UW', 'Wa', 'The most north-westerly region, featuring the Wa Naa''s Palace, the Wechiau Community Hippo Sanctuary, and unique traditional culture and architecture.', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=800&q=80', 'bg-purple-700'),
  ('bono', 'Bono', 9, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'BO', 'Sunyani', 'The "Garden City" region, known for its lush vegetation, numerous rivers, and the serene Tanoso Forest Reserve. The region is an important agricultural zone.', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=800&q=80', 'bg-green-600'),
  ('bono-east', 'Bono East', 10, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'BE', 'Techiman', 'Home to the spectacular Kintampo Waterfalls and the Techiman market, one of Ghana''s largest. The region sits at the geographic centre of Ghana.', 'https://images.unsplash.com/photo-1564419320461-6870880221ad?w=800&q=80', 'bg-cyan-700'),
  ('ahafo', 'Ahafo', 11, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'AF', 'Goaso', 'A newer region known for its rich forests, abundant water resources, and gold mining. The region offers pristine natural landscapes and authentic rural Ghana experiences.', 'https://images.unsplash.com/photo-1598512752271-33f913a5af13?w=800&q=80', 'bg-amber-700'),
  ('savannah', 'Savannah', 12, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'SV', 'Damongo', 'Gateway to Mole National Park — Ghana''s largest wildlife sanctuary — where visitors can spot elephants, antelopes, warthogs, and over 300 bird species in their natural habitat.', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=800&q=80', 'bg-yellow-700'),
  ('north-east', 'North East', 13, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'NE', 'Nalerigu', 'One of Ghana''s newest regions, known for the Gambaga Escarpment, Nalerigu Fort, and diverse ethnic communities with rich cultural traditions.', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=800&q=80', 'bg-rose-700'),
  ('oti', 'Oti', 14, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'OT', 'Dambai', 'A region bordering Togo and Benin, known for its scenic riverside landscapes along the Oti River, diverse ethnic groups, and the unique Kpassa culture.', 'https://images.unsplash.com/photo-1564419320461-6870880221ad?w=800&q=80', 'bg-indigo-700'),
  ('western-north', 'Western North', 15, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'WN2', 'Sefwi Wiawso', 'Known for its vast cocoa farms, dense tropical forests, and gold mines. The region offers a glimpse into rural Ghanaian life and natural beauty.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 'bg-fuchsia-700')
insert into public.destinations (id, name, position, created_at, updated_at, status, archived_at, slug, region_id, type, short_description, description, image_url, estimated_cost, rating, review_count, featured, details) values
  ('cape-coast-castle', 'Cape Coast Castle', 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'cape-coast-castle', 'central', 'historical', 'A UNESCO World Heritage Site and former slave castle offering a powerful and moving journey through Ghana''s colonial history.', 'Cape Coast Castle is one of about forty "slave castles", or large commercial forts, built on the Gold Coast of West Africa by European traders. It was originally built by the Swedes for trade in timber and gold, but was later used in the Atlantic slave trade, and is the largest of these castles. Today it is a museum and UNESCO World Heritage Site that offers a sobering and deeply moving experience, allowing visitors to understand the horrors of the transatlantic slave trade while celebrating Ghana''s resilience and independence.', 'https://images.unsplash.com/photo-1575986767340-5d17ae767ab0?w=800&q=80', 250, 4.8, 2847, true, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1575986767340-5d17ae767ab0?w=1200&q=85","alt":"Cape Coast Castle exterior"},{"id":"g2","url":"https://images.unsplash.com/photo-1582555172866-f73bb12a2ab3?w=1200&q=85","alt":"Castle courtyard"},{"id":"g3","url":"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=85","alt":"Coastal view"}],"activities":[{"id":"a1","name":"Guided Museum Tour","description":"A comprehensive guided tour through the castle''s dungeons, museum and the Door of No Return.","duration":"2 hours","cost":30},{"id":"a2","name":"Canopy Walk","description":"Walk along the castle''s battlements with sweeping views of the Atlantic Ocean.","duration":"30 mins","cost":0},{"id":"a3","name":"Photography Session","description":"Capture the castle''s stunning architecture and ocean backdrop at sunset.","duration":"1 hour","cost":0},{"id":"a4","name":"Cultural Performance","description":"Watch traditional Fante drumming and dance performances in the castle courtyard.","duration":"1 hour","cost":20}],"thingsToDo":["Visit the slave dungeons and reflect on history","Walk through the Door of No Return","Explore the castle museum","Watch the sunset over the Atlantic from the battlements","Visit the nearby Cape Coast market","Explore the town''s colonial architecture"],"openingHours":"Tuesday – Sunday: 9:00 AM – 4:30 PM","entryFee":80,"safetyInfo":"Cape Coast is generally safe for tourists. Keep belongings secure in crowded market areas. Dress modestly when visiting the castle as a sign of respect.","transportOptions":[{"type":"Bus","description":"STC or VIP buses from Accra (Tudu) to Cape Coast","estimatedCost":"₵30–50","duration":"3 hours"},{"type":"Trotro","description":"Shared minibuses from Kaneshie or Tudu Market, Accra","estimatedCost":"₵20–35","duration":"3.5 hours"},{"type":"Taxi","description":"Shared taxis from Accra","estimatedCost":"₵40–60","duration":"3 hours"}],"nearbyDestinations":["elmina-castle","kakum-national-park"],"latitude":5.1041,"longitude":-1.2424,"tags":["history","UNESCO","heritage","museum","slavery","colonial","culture"],"bestTimeToVisit":"November to March (dry season)"}'::jsonb),
  ('kakum-national-park', 'Kakum National Park', 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'kakum-national-park', 'central', 'national-park', 'Walk among the treetops on Africa''s only canopy walkway in this spectacular tropical rainforest teeming with wildlife.', 'Kakum National Park is a tropical rainforest reserve located about 30 kilometres north of Cape Coast. The park is famous for its canopy walkway — a series of rope and board bridges suspended 30 metres above the forest floor — which offers breathtaking views over the rainforest canopy. The park covers approximately 375 square kilometres and is home to a remarkable array of wildlife including forest elephants, bongo antelopes, leopards, and over 400 butterfly species.', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=800&q=80', 200, 4.7, 3214, true, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=1200&q=85","alt":"Kakum canopy walkway"},{"id":"g2","url":"https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=1200&q=85","alt":"Rainforest canopy"},{"id":"g3","url":"https://images.unsplash.com/photo-1598512752271-33f913a5af13?w=1200&q=85","alt":"Forest trail"}],"activities":[{"id":"a1","name":"Canopy Walkway","description":"Walk 330 metres of swaying rope bridges high above the rainforest floor.","duration":"1.5 hours","cost":60},{"id":"a2","name":"Bird Watching","description":"Spot rare forest birds with a knowledgeable guide.","duration":"2 hours","cost":50},{"id":"a3","name":"Night Safari","description":"Guided nocturnal walk to spot forest wildlife.","duration":"2 hours","cost":80},{"id":"a4","name":"Nature Trail Hike","description":"Guided forest floor hike to learn about medicinal plants and wildlife.","duration":"2 hours","cost":40}],"thingsToDo":["Walk the famous canopy walkway","Go bird watching with expert guides","Learn about rainforest ecology on guided trails","Night walk for nocturnal animals","Visit the visitor centre and museum"],"openingHours":"Daily: 7:00 AM – 5:00 PM","entryFee":60,"safetyInfo":"The canopy walkway can sway — visitors with vertigo or mobility issues should take care. Wear sturdy shoes. Follow all guide instructions.","transportOptions":[{"type":"Trotro","description":"From Cape Coast to Abrafo junction, then short taxi ride","estimatedCost":"₵15–25","duration":"45 mins"},{"type":"Taxi","description":"Chartered taxi from Cape Coast","estimatedCost":"₵60–100","duration":"40 mins"}],"nearbyDestinations":["cape-coast-castle","elmina-castle"],"latitude":5.3521,"longitude":-1.3847,"tags":["nature","wildlife","canopy","rainforest","hiking","birds","eco-tourism"],"bestTimeToVisit":"November to April (drier months)"}'::jsonb),
  ('mole-national-park', 'Mole National Park', 2, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'mole-national-park', 'savannah', 'wildlife', 'Ghana''s premier safari destination, offering walking safaris to see elephants, hippos, and hundreds of wildlife species up close.', 'Mole National Park is Ghana''s largest wildlife sanctuary, covering an area of approximately 4,840 square kilometres. The park is home to more than 90 mammal species, including the largest elephant population in Ghana, as well as buffalo, hippos, kob, roan antelope, waterbuck, warthogs, baboons, green monkeys, and over 300 bird species. Walking safaris led by armed rangers offer an up-close and authentic wildlife experience unlike anywhere else in West Africa.', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=800&q=80', 600, 4.9, 1876, true, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=1200&q=85","alt":"Elephants at Mole"},{"id":"g2","url":"https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=1200&q=85","alt":"Savannah landscape"},{"id":"g3","url":"https://images.unsplash.com/photo-1598512752271-33f913a5af13?w=1200&q=85","alt":"Warthog family"}],"activities":[{"id":"a1","name":"Walking Safari","description":"Early morning guided walk to encounter elephants and other wildlife.","duration":"2 hours","cost":80},{"id":"a2","name":"Jeep Safari","description":"Vehicle-based game drive covering more of the park.","duration":"3 hours","cost":200},{"id":"a3","name":"Bird Watching","description":"Over 300 species to spot with expert birding guides.","duration":"2 hours","cost":60},{"id":"a4","name":"Sunset Viewing","description":"Watch the stunning savannah sunset from the Mole Motel terrace.","duration":"1 hour","cost":0}],"thingsToDo":["Take an early morning walking safari with armed rangers","Watch elephants at the watering holes","Go bird watching in diverse habitats","Visit Larabanga Mosque (nearby)","Explore the Mole Motel observation deck","Night game drives"],"openingHours":"Daily: 6:00 AM – 6:00 PM","entryFee":100,"safetyInfo":"Always stay with your armed ranger guide. Never approach wildlife, especially elephants, without guidance. Keep voices low and move slowly.","transportOptions":[{"type":"Bus","description":"STC bus from Accra/Kumasi to Tamale, then local transport to Larabanga/Mole","estimatedCost":"₵80–150","duration":"10–12 hours"},{"type":"Domestic Flight","description":"Africa World Airlines Accra to Tamale, then ground transport","estimatedCost":"₵500–1000","duration":"1 hour flight + 3 hours drive"}],"nearbyDestinations":["larabanga-mosque"],"latitude":9.2667,"longitude":-1.8478,"tags":["safari","wildlife","elephants","nature","birds","walking safari","conservation"],"bestTimeToVisit":"December to April (dry season, animals near waterholes)"}'::jsonb),
  ('elmina-castle', 'Elmina Castle', 3, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'elmina-castle', 'central', 'historical', 'The oldest European building in sub-Saharan Africa — a hauntingly beautiful Portuguese fort now preserved as a UNESCO World Heritage Site.', 'Elmina Castle — officially São Jorge da Mina — is the oldest European building in existence sub-Saharan Africa, built by the Portuguese in 1482. Like Cape Coast Castle, it was used extensively in the transatlantic slave trade. The castle overlooks the charming fishing town of Elmina and provides visitors with an emotionally powerful experience exploring its dungeons, courtyard, and the infamous Door of No Return. A UNESCO World Heritage Site.', 'https://images.unsplash.com/photo-1582555172866-f73bb12a2ab3?w=800&q=80', 220, 4.7, 2193, true, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1582555172866-f73bb12a2ab3?w=1200&q=85","alt":"Elmina Castle exterior"},{"id":"g2","url":"https://images.unsplash.com/photo-1575986767340-5d17ae767ab0?w=1200&q=85","alt":"Castle and fishing harbour"}],"activities":[{"id":"a1","name":"Guided Historical Tour","description":"Comprehensive tour through the castle''s dungeons and museum.","duration":"2 hours","cost":80},{"id":"a2","name":"Fishing Harbour Walk","description":"Explore the colourful Elmina fishing harbour and local market.","duration":"1 hour","cost":0},{"id":"a3","name":"Sunset Photography","description":"Spectacular sunset views over the Atlantic from the castle walls.","duration":"1 hour","cost":0}],"thingsToDo":["Tour the historic dungeons and the Door of No Return","Visit the castle museum","Walk the Elmina fishing harbour","Explore the colonial town of Elmina","Visit the Java Hill viewpoint"],"openingHours":"Tuesday – Sunday: 9:00 AM – 4:30 PM","entryFee":80,"safetyInfo":"The castle streets and harbour area are safe. Exercise normal caution with valuables in the market.","transportOptions":[{"type":"Trotro","description":"From Cape Coast market to Elmina","estimatedCost":"₵5–10","duration":"20 mins"},{"type":"Taxi","description":"Chartered from Cape Coast","estimatedCost":"₵30–50","duration":"15 mins"}],"nearbyDestinations":["cape-coast-castle","kakum-national-park"],"latitude":5.084,"longitude":-1.3498,"tags":["history","UNESCO","colonial","portuguese","slavery","heritage","museum"],"bestTimeToVisit":"November to March"}'::jsonb),
  ('labadi-beach', 'Labadi Beach', 4, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'labadi-beach', 'greater-accra', 'beach', 'Accra''s most vibrant beach — a colourful mix of music, food, horse riding, and the warm energy of Ghanaian coastal culture.', 'Labadi Beach (La Pleasure Beach) is Accra''s most popular and vibrant beach, stretching along the Gulf of Guinea east of the city centre. The beach is a lively social hub, especially on weekends and public holidays, when it fills with music, food vendors, horse riding, beach sports, and the infectious energy of Accra. It offers a wonderful window into contemporary Ghanaian urban culture and is a favourite meeting place for locals and visitors alike.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 150, 4.2, 4521, true, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=85","alt":"Labadi Beach"},{"id":"g2","url":"https://images.unsplash.com/photo-1589825743636-23a879d4b8e2?w=1200&q=85","alt":"Beach activities"}],"activities":[{"id":"a1","name":"Horse Riding","description":"Ride horses along the beach shoreline.","duration":"30 mins","cost":80},{"id":"a2","name":"Beach Volleyball","description":"Join a game of beach volleyball on the sand.","duration":"1 hour","cost":20},{"id":"a3","name":"Live Music","description":"Enjoy live highlife and Afrobeats music, especially on weekends.","duration":"Evening","cost":0},{"id":"a4","name":"Seafood Dining","description":"Fresh seafood grills along the beachfront restaurants.","duration":"1 hour","cost":50}],"thingsToDo":["Swim in the ocean (be cautious of currents)","Enjoy horse riding along the shore","Eat grilled seafood at beachside restaurants","Experience live highlife music on weekends","Watch the spectacular sunset","Play beach sports"],"openingHours":"Daily: 8:00 AM – 10:00 PM","entryFee":20,"safetyInfo":"Swim with caution — the Atlantic can have strong currents. Keep valuables secure. The beach is well-patrolled but stay alert in crowded areas.","transportOptions":[{"type":"Trotro","description":"From Accra centre towards Tema, alight at Labadi","estimatedCost":"₵3–8","duration":"20 mins"},{"type":"Uber/Bolt","description":"Ride-hailing from anywhere in Accra","estimatedCost":"₵20–50","duration":"15–30 mins"}],"nearbyDestinations":["kwame-nkrumah-memorial-park","ada-foah"],"latitude":5.5577,"longitude":-0.1527,"tags":["beach","ocean","nightlife","music","food","social","coastal"],"bestTimeToVisit":"October to March (cooler, less rainy)"}'::jsonb),
  ('kwame-nkrumah-memorial-park', 'Kwame Nkrumah Memorial Park', 5, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'kwame-nkrumah-memorial-park', 'greater-accra', 'historical', 'A tribute to Ghana''s founding father — the mausoleum, museum, and gardens mark the very spot where independence was declared in 1957.', 'The Kwame Nkrumah Memorial Park and Mausoleum in central Accra is dedicated to Ghana''s first president and founding father, Dr. Kwame Nkrumah. The park features a striking mausoleum housing the remains of Nkrumah and his wife, a museum documenting his life and legacy, and beautifully landscaped gardens. It is one of the most significant political heritage sites in Africa, marking the spot where Ghana''s independence was declared on 6 March 1957.', 'https://images.unsplash.com/photo-1589825743636-23a879d4b8e2?w=800&q=80', 80, 4.5, 1892, false, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1589825743636-23a879d4b8e2?w=1200&q=85","alt":"Nkrumah Memorial Park"}],"activities":[{"id":"a1","name":"Museum Tour","description":"Explore artefacts and photographs documenting Nkrumah''s life and Ghana''s independence movement.","duration":"1.5 hours","cost":30},{"id":"a2","name":"Garden Walk","description":"Stroll the peaceful manicured gardens and take photos of the striking mausoleum.","duration":"30 mins","cost":0}],"thingsToDo":["Visit the mausoleum of Dr. Kwame Nkrumah","Explore the independence museum","Photograph the iconic statue and fountain","Walk the landscaped memorial gardens","Learn about Pan-Africanism and Ghana''s independence"],"openingHours":"Tuesday – Sunday: 9:00 AM – 5:00 PM","entryFee":30,"safetyInfo":"The park is safe and well-maintained. It is located in central Accra, close to Parliament House.","transportOptions":[{"type":"Trotro","description":"From any part of Accra, ask for Kinbu or High Street","estimatedCost":"₵2–8","duration":"10–30 mins"},{"type":"Uber/Bolt","description":"Ride-hailing from anywhere in Accra","estimatedCost":"₵15–40","duration":"10–25 mins"}],"nearbyDestinations":["labadi-beach"],"latitude":5.5471,"longitude":-0.2008,"tags":["history","independence","politics","culture","Nkrumah","museum","landmark"],"bestTimeToVisit":"Year-round"}'::jsonb),
  ('wli-waterfalls', 'Wli Waterfalls', 6, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'wli-waterfalls', 'volta', 'waterfall', 'The highest waterfalls in West Africa — a magnificent 60-metre cascade hidden in lush Volta Region forest, home to thousands of fruit bats.', 'The Wli Waterfalls, also known as the Agumatsa Falls, are the highest waterfalls in West Africa, dropping 60 metres in a spectacular cascade into a cool pool surrounded by lush tropical forest. Located near the town of Hohoe in the Volta Region, the falls are home to a colony of straw-coloured fruit bats and diverse bird species. A 45-minute hike through scenic forest brings you to the lower falls, with a more challenging trail leading to the upper falls.', 'https://images.unsplash.com/photo-1564419320461-6870880221ad?w=800&q=80', 180, 4.8, 1654, true, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1564419320461-6870880221ad?w=1200&q=85","alt":"Wli Waterfalls"},{"id":"g2","url":"https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=1200&q=85","alt":"Forest trail to Wli"}],"activities":[{"id":"a1","name":"Lower Falls Hike","description":"Easy 45-minute hike through forest to the stunning lower waterfall pool.","duration":"2 hours","cost":40},{"id":"a2","name":"Upper Falls Trek","description":"Challenging 3-hour trek to the upper falls — incredible views.","duration":"6 hours","cost":80},{"id":"a3","name":"Bat Colony Observation","description":"Watch thousands of fruit bats emerge at dusk.","duration":"1 hour","cost":0},{"id":"a4","name":"Swimming","description":"Cool off in the natural pool at the base of the falls.","duration":"Flexible","cost":0}],"thingsToDo":["Hike to the lower and upper waterfalls","Swim in the cool natural pool","Watch the fruit bat colony at dusk","Spot forest birds and butterflies","Photography of the spectacular falls"],"openingHours":"Daily: 7:00 AM – 5:00 PM","entryFee":40,"safetyInfo":"Wear waterproof shoes with good grip for the hike. The trail can be slippery. Swimming is safe in the pool area. Hire a local guide for the upper falls trek.","transportOptions":[{"type":"Bus","description":"VIP bus from Accra to Hohoe, then taxi to Wli","estimatedCost":"₵60–90","duration":"5 hours"},{"type":"Shared Taxi","description":"From Hohoe town to Wli village","estimatedCost":"₵15–25","duration":"30 mins"}],"nearbyDestinations":["lake-volta"],"latitude":7.0667,"longitude":0.5167,"tags":["waterfall","nature","hiking","swimming","bats","birds","eco-tourism"],"bestTimeToVisit":"March to October (waterfall is most powerful during rainy season)"}'::jsonb),
  ('aburi-botanical-gardens', 'Aburi Botanical Gardens', 7, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'aburi-botanical-gardens', 'eastern', 'botanical', 'A refreshing colonial-era botanical garden in the cool Akwapim Hills — a peaceful green escape just an hour from Accra.', 'The Aburi Botanical Gardens, established by the British colonial government in 1890, are nestled in the cool misty hills of the Akwapim Ridge, just 35 kilometres north of Accra. Spanning 64.8 hectares, the gardens contain an impressive collection of tropical plants, towering mahogany trees, exotic palms, cacti, and orchids. The elevation gives Aburi a pleasant, refreshing climate that is a welcome escape from the heat of Accra. The gardens are a favourite day-trip destination for Accra residents.', 'https://images.unsplash.com/photo-1598512752271-33f913a5af13?w=800&q=80', 100, 4.4, 1287, false, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1598512752271-33f913a5af13?w=1200&q=85","alt":"Aburi gardens"},{"id":"g2","url":"https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=1200&q=85","alt":"Tropical trees"}],"activities":[{"id":"a1","name":"Garden Walk","description":"Stroll through 64 hectares of magnificent tropical plants and trees.","duration":"2 hours","cost":20},{"id":"a2","name":"Picnic","description":"Bring food and enjoy a peaceful picnic under towering mahogany trees.","duration":"Flexible","cost":0},{"id":"a3","name":"Photography","description":"Capture the lush greenery and colonial-era architecture.","duration":"1 hour","cost":0}],"thingsToDo":["Walk through the collection of over 5,000 tropical plant species","Enjoy a picnic under the old mahogany trees","Visit the curio market at the gates","Explore the colonial-era rest house","Cool off in the highland breeze"],"openingHours":"Daily: 7:30 AM – 6:00 PM","entryFee":20,"safetyInfo":"The gardens are very safe. Good for families. Watch your step on some uneven paths.","transportOptions":[{"type":"Trotro","description":"From Accra''s 37 Station or Madina towards Aburi","estimatedCost":"₵10–20","duration":"1 hour"},{"type":"Taxi","description":"Chartered taxi from Accra","estimatedCost":"₵80–150","duration":"50 mins"}],"nearbyDestinations":["kwame-nkrumah-memorial-park"],"latitude":5.8507,"longitude":-0.1768,"tags":["nature","botanical","gardens","colonial","day-trip","Accra","cool climate"],"bestTimeToVisit":"Year-round (coolest November to January)"}'::jsonb),
  ('lake-volta', 'Lake Volta', 8, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'lake-volta', 'volta', 'lake', 'One of the world''s largest man-made lakes — take a scenic lake ferry, watch for hippos, and experience authentic fishing village life.', 'Lake Volta is one of the world''s largest man-made lakes by surface area, created by the construction of the Akosombo Dam in 1965. Stretching over 8,500 square kilometres, the lake cuts through Ghana''s Eastern and Volta regions, offering spectacular scenery, fishing villages, and a unique way to travel — by ferry from Akosombo to Yeji. The lake is home to diverse wildlife including hippos, Nile crocodiles, and hundreds of bird species. A boat trip on Lake Volta is a deeply memorable Ghanaian experience.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 300, 4.5, 892, false, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=85","alt":"Lake Volta"},{"id":"g2","url":"https://images.unsplash.com/photo-1564419320461-6870880221ad?w=1200&q=85","alt":"Lake sunset"}],"activities":[{"id":"a1","name":"Lake Ferry Journey","description":"Multi-day ferry journey from Akosombo to Yeji through the heart of the lake.","duration":"20 hours","cost":120},{"id":"a2","name":"Boat Safari","description":"Smaller boat tours to spot hippos, crocodiles and birds.","duration":"3 hours","cost":150},{"id":"a3","name":"Fishing Experience","description":"Join local fishermen on an early morning fishing trip.","duration":"4 hours","cost":80}],"thingsToDo":["Take the Akosombo to Yeji lake ferry","Spot hippos and crocodiles on a boat safari","Visit the Akosombo Dam viewpoint","Experience fishing village life","Bird watching along the lake shores"],"openingHours":"Ferry departures: Check GVTC schedule","entryFee":0,"safetyInfo":"Use life jackets on all boat trips. Do not swim in the lake — it harbours bilharzia parasites and there are crocodiles.","transportOptions":[{"type":"Bus","description":"STC or trotro from Accra to Akosombo","estimatedCost":"₵25–50","duration":"2 hours"}],"nearbyDestinations":["wli-waterfalls"],"latitude":7,"longitude":0.15,"tags":["lake","ferry","hippos","birds","fishing","dam","nature"],"bestTimeToVisit":"November to March"}'::jsonb),
  ('nzulezu-stilt-village', 'Nzulezu Stilt Village', 9, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'nzulezu-stilt-village', 'western', 'cultural', 'A living village built on stilts over a lake — inhabited for over 500 years by the Nzema people and inscribed as a UNESCO World Heritage Site.', 'Nzulezu is a remarkable village built entirely on stilts over Lake Tadane in the Western Region of Ghana. Home to around 500 people of the Nzema ethnic group, the village has existed for over 500 years. Residents move between homes by canoe, and the village features a church, school, and traditional shrine — all on water. It is a UNESCO World Heritage-listed site that offers one of the most extraordinary cultural experiences in Africa.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 200, 4.6, 743, true, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=85","alt":"Nzulezu stilt village"}],"activities":[{"id":"a1","name":"Canoe Trip","description":"45-minute canoe ride through forest waterways to reach the village.","duration":"1.5 hours","cost":50},{"id":"a2","name":"Village Tour","description":"Walk the floating boardwalks, visit the school, church, and shrine.","duration":"1 hour","cost":30},{"id":"a3","name":"Cultural Meeting","description":"Meet the village chief and learn about Nzema traditions.","duration":"30 mins","cost":20}],"thingsToDo":["Canoe through the forest to the village","Walk the floating boardwalks","Meet village residents and learn their story","Visit the floating church and school","See the traditional shrine"],"openingHours":"Daily: 7:00 AM – 4:00 PM","entryFee":50,"safetyInfo":"Life jackets are provided for the canoe trip. Visitors must respect the sacred areas of the village. Photography of residents requires permission.","transportOptions":[{"type":"Bus","description":"STC/VIP from Accra to Beyin junction, then taxi to launch site","estimatedCost":"₵80–120","duration":"5 hours"}],"nearbyDestinations":["kakum-national-park"],"latitude":4.9167,"longitude":-2.5833,"tags":["UNESCO","cultural","stilt village","water","canoe","Nzema","heritage"],"bestTimeToVisit":"November to April (dry season, calmer waters)"}'::jsonb),
  ('manhyia-palace', 'Manhyia Palace', 10, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'manhyia-palace', 'ashanti', 'cultural', 'The palace of the Asante King — explore the royal museum, see historic artefacts, and learn the extraordinary story of the Ashanti kingdom.', 'Manhyia Palace in Kumasi is the official residence and headquarters of the Asantehene — the king of the Ashanti people. The current palace, built in 1974 to replace the original colonial-era building, houses a fascinating museum that traces the history of the Ashanti kingdom from the 17th century to the present day. Visitors can see royal artefacts, learn about the legendary Golden Stool (Sika Dwa), and understand the remarkable story of Ashanti resistance to British colonialism.', 'https://images.unsplash.com/photo-1565373677928-80cf5b789d2e?w=800&q=80', 150, 4.6, 1543, true, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1565373677928-80cf5b789d2e?w=1200&q=85","alt":"Manhyia Palace"}],"activities":[{"id":"a1","name":"Museum Tour","description":"Guided tour through the Manhyia Palace Museum and royal collections.","duration":"1.5 hours","cost":40},{"id":"a2","name":"Cultural Talk","description":"Learn about Ashanti royal customs and the significance of the Golden Stool.","duration":"30 mins","cost":0}],"thingsToDo":["Explore the royal palace museum","Learn about the Ashanti kingdom and the Golden Stool","See historical royal artefacts","Understand Ashanti governance and traditions","Visit the nearby Kumasi Cultural Centre"],"openingHours":"Monday – Saturday: 9:00 AM – 4:00 PM","entryFee":40,"safetyInfo":"Dress modestly and respectfully when visiting the palace. Photography may be restricted in certain areas.","transportOptions":[{"type":"Trotro","description":"From Kumasi Kejetia market towards Manhyia","estimatedCost":"₵3–8","duration":"15 mins"},{"type":"Taxi","description":"From anywhere in Kumasi","estimatedCost":"₵20–40","duration":"10–20 mins"}],"nearbyDestinations":["kumasi-cultural-centre"],"latitude":6.7167,"longitude":-1.6167,"tags":["culture","Ashanti","royal","history","museum","traditional","Kumasi"],"bestTimeToVisit":"Year-round"}'::jsonb),
  ('kumasi-cultural-centre', 'Kumasi Cultural Centre', 11, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'kumasi-cultural-centre', 'ashanti', 'cultural', 'Ghana''s largest cultural complex — watch Kente weavers, browse master craftsmen, and immerse yourself in Ashanti artistic traditions.', 'The Kumasi National Cultural Centre is the largest cultural complex in Ghana, serving as a hub for Ashanti arts, crafts, and cultural expression. The centre houses a museum, an open-air market with artisans selling Kente cloth, wood carvings, brass castings, and leather goods, as well as performance spaces for traditional music and dance. It is a living, breathing showcase of Ghanaian creativity and craftsmanship.', 'https://images.unsplash.com/photo-1565373677928-80cf5b789d2e?w=800&q=80', 120, 4.4, 987, false, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1565373677928-80cf5b789d2e?w=1200&q=85","alt":"Cultural Centre crafts"}],"activities":[{"id":"a1","name":"Craft Market Shopping","description":"Browse and buy Kente cloth, carvings, brass, and leather goods from master artisans.","duration":"2 hours","cost":0},{"id":"a2","name":"Kente Weaving Demo","description":"Watch traditional Kente cloth being woven on a hand loom.","duration":"30 mins","cost":20},{"id":"a3","name":"Cultural Performance","description":"Traditional Ashanti drumming and dance shows.","duration":"1 hour","cost":30}],"thingsToDo":["Buy authentic Kente cloth direct from weavers","Watch traditional drumming and dance","Browse the craft market for souvenirs","Visit the cultural museum","See wood carving and brass casting demonstrations"],"openingHours":"Daily: 8:00 AM – 5:00 PM","entryFee":10,"safetyInfo":"Bargaining is expected in the craft market. Keep valuables secure.","transportOptions":[{"type":"Trotro","description":"From Kejetia market in Kumasi","estimatedCost":"₵2–5","duration":"10 mins"}],"nearbyDestinations":["manhyia-palace"],"latitude":6.6885,"longitude":-1.6236,"tags":["culture","crafts","Kente","Ashanti","shopping","traditional","art"],"bestTimeToVisit":"Year-round"}'::jsonb),
  ('ada-foah', 'Ada Foah', 12, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ada-foah', 'greater-accra', 'beach', 'Where the Volta River meets the sea — a beautiful resort town perfect for water sports, river cruises, and peaceful beach escapes.', 'Ada Foah is a stunning coastal resort town located where the Volta River meets the Atlantic Ocean, about 100 kilometres east of Accra. The town is famous for its idyllic beach resorts, water sports, boat cruises on the river, and the unique experience of jumping between the warm Volta River and the cool Atlantic Ocean. Ada is a favourite weekend getaway for Accra residents and offers a more relaxed, upscale beach experience than Labadi.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', 400, 4.6, 1345, false, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1200&q=85","alt":"Ada Foah beach"}],"activities":[{"id":"a1","name":"River Cruise","description":"Boat cruise on the Volta River to spot birds and hippos.","duration":"2 hours","cost":100},{"id":"a2","name":"Water Sports","description":"Jet skiing, kayaking, and paddleboarding.","duration":"Flexible","cost":80},{"id":"a3","name":"River-Ocean Swim","description":"Unique experience swimming between the Volta River and Atlantic Ocean.","duration":"1 hour","cost":0}],"thingsToDo":["Stay at one of Ada''s beautiful beach resorts","Take a river cruise on the Volta","Try water sports on the lagoon","Spot hippos upriver","Visit Manet Paradise Beach Resort","Watch the sunset at the river mouth"],"safetyInfo":"The ocean currents at Ada can be strong — swim only in designated safe areas. Life jackets are mandatory for boat trips.","transportOptions":[{"type":"Trotro","description":"From Accra Tema Station to Ada junction, then taxi to Ada Foah","estimatedCost":"₵30–50","duration":"2.5 hours"},{"type":"Taxi","description":"Chartered taxi from Accra","estimatedCost":"₵200–350","duration":"1.5 hours"}],"nearbyDestinations":["labadi-beach"],"latitude":5.7667,"longitude":0.6333,"tags":["beach","resort","water sports","river","Volta","relaxation","weekend"],"bestTimeToVisit":"November to April"}'::jsonb),
  ('paga-crocodile-pond', 'Paga Crocodile Pond', 13, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'paga-crocodile-pond', 'upper-east', 'cultural', 'Touch and sit on wild sacred crocodiles — one of the world''s most extraordinary wildlife encounters, rooted in centuries of Kasena tradition.', 'The Paga Crocodile Pond near the town of Paga, close to the Burkina Faso border, is one of Ghana''s most extraordinary attractions. Local tradition holds that the crocodiles of Paga are sacred — believed to be the souls of ancestors — and they have co-existed peacefully with the community for generations. Visitors can sit on and even touch these wild crocodiles with the assistance of knowledgeable local guides. It is a truly unique and unforgettable experience.', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=800&q=80', 180, 4.7, 876, false, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=1200&q=85","alt":"Paga crocodile"}],"activities":[{"id":"a1","name":"Crocodile Interaction","description":"Guided interaction with the sacred crocodiles — sit on or touch them safely.","duration":"1 hour","cost":50},{"id":"a2","name":"Cultural Tour","description":"Learn about Kasena traditions and the spiritual significance of the crocodiles.","duration":"30 mins","cost":20}],"thingsToDo":["Touch and photograph the sacred crocodiles","Learn about the Kasena people''s relationship with the crocodiles","Visit the Nania Dam crocodile pond","Explore the nearby town of Paga","Cross briefly into Burkina Faso at the nearby border"],"openingHours":"Daily: 7:00 AM – 5:00 PM","entryFee":50,"safetyInfo":"Always follow your guide''s instructions. The crocodiles are genuinely wild — never approach them without a guide. The interaction is safe when done properly.","transportOptions":[{"type":"Bus","description":"STC from Accra to Bolgatanga, then trotro to Paga","estimatedCost":"₵120–180","duration":"14–16 hours"},{"type":"Domestic Flight","description":"Flight to Tamale, then bus to Bolgatanga, then trotro to Paga","estimatedCost":"₵600–1200","duration":"6 hours total"}],"nearbyDestinations":[],"latitude":10.9833,"longitude":-1.1167,"tags":["wildlife","cultural","crocodiles","sacred","unique","Upper East","Kasena"],"bestTimeToVisit":"November to March (dry season)"}'::jsonb),
  ('kintampo-waterfalls', 'Kintampo Waterfalls', 14, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'kintampo-waterfalls', 'bono-east', 'waterfall', 'Spectacular 70-metre waterfalls at the geographic heart of Ghana — swim in the natural pool and hike scenic forest trails.', 'The Kintampo Waterfalls, located near the town of Kintampo in Bono East Region, are one of Ghana''s most spectacular natural attractions. The falls cascade about 70 metres over rugged rocky terrain, surrounded by lush tropical vegetation. A refreshing swimming pool at the base provides a natural swimming experience. The site is especially vibrant during the rainy season when the falls are at full force. Kintampo sits at the geographic centre of Ghana.', 'https://images.unsplash.com/photo-1564419320461-6870880221ad?w=800&q=80', 150, 4.5, 643, false, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1564419320461-6870880221ad?w=1200&q=85","alt":"Kintampo Waterfalls"}],"activities":[{"id":"a1","name":"Waterfall Hike","description":"Guided hike down to the base of the falls through lush vegetation.","duration":"1.5 hours","cost":30},{"id":"a2","name":"Swimming","description":"Swim in the natural pool at the base of the falls.","duration":"Flexible","cost":0},{"id":"a3","name":"Nature Trail","description":"Explore the surrounding forest trails.","duration":"1 hour","cost":20}],"thingsToDo":["Hike to the base of the waterfalls","Swim in the natural pool","Enjoy a picnic in the surrounding forest","Visit the geographic centre of Ghana monument"],"openingHours":"Daily: 8:00 AM – 5:00 PM","entryFee":30,"safetyInfo":"Wear sturdy, non-slip footwear for the hike. Do not swim near the main cascade. The trail can be muddy in rainy season.","transportOptions":[{"type":"Bus","description":"STC/VIP from Accra or Kumasi to Kintampo","estimatedCost":"₵40–80","duration":"6–8 hours"}],"nearbyDestinations":[],"latitude":8.0667,"longitude":-1.7333,"tags":["waterfall","nature","swimming","hiking","tropical","Bono East"],"bestTimeToVisit":"June to October (peak flow during rainy season)"}'::jsonb),
  ('boti-falls', 'Boti Falls', 15, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'boti-falls', 'eastern', 'waterfall', 'Ghana''s unique twin waterfalls — male and female falls in a romantic forest reserve, complete with the legendary luck-bringing Love Tree.', 'Boti Falls in the Eastern Region of Ghana are unique twin waterfalls that cascade side by side, locally known as the "male" and "female" falls. During the rainy season they merge into a spectacular single curtain of water. The site features a beautiful forest reserve with a love tree — a tree with two trunks joined at the top, said to bring luck to couples who hold hands and walk around it three times. A popular and romantic destination for both locals and tourists.', 'https://images.unsplash.com/photo-1564419320461-6870880221ad?w=800&q=80', 120, 4.4, 892, false, '{"gallery":[{"id":"g1","url":"https://images.unsplash.com/photo-1564419320461-6870880221ad?w=1200&q=85","alt":"Boti Falls"}],"activities":[{"id":"a1","name":"Falls Hike","description":"Short guided hike to the twin waterfalls through forest.","duration":"1 hour","cost":25},{"id":"a2","name":"Love Tree Walk","description":"Walk around the famous joined Love Tree for good luck.","duration":"15 mins","cost":0},{"id":"a3","name":"Swimming","description":"Cool off in the pools below the falls.","duration":"Flexible","cost":0}],"thingsToDo":["Hike to the twin waterfalls","Walk around the Love Tree","Swim in the waterfall pool","Photography in the scenic forest"],"openingHours":"Daily: 8:00 AM – 5:00 PM","entryFee":25,"safetyInfo":"Wear waterproof footwear. The path can be muddy. Do not swim directly under the falls.","transportOptions":[{"type":"Trotro","description":"From Accra to Koforidua, then trotro towards Boti","estimatedCost":"₵20–35","duration":"2.5 hours"}],"nearbyDestinations":["aburi-botanical-gardens"],"latitude":6.2167,"longitude":-0.1167,"tags":["waterfall","nature","romantic","swimming","hiking","Eastern","forest"],"bestTimeToVisit":"June to September (rainy season, falls at full power)"}'::jsonb),
  ('bunso-eco-park', 'Bunso Eco Park (Bunso Arboretum)', 16, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bunso-eco-park', 'eastern', 'botanical', 'A forest reserve in the Eastern Region with Ghana''s second canopy walkway, nature trails and a zipline.', 'Bunso Eco Park, long known as the Bunso Arboretum, is a forest reserve just south of the town of Bunso in the Eastern Region, off the Accra to Kumasi road. It protects a patch of semi-deciduous forest with a large collection of indigenous and introduced trees, and is a favourite stop for school groups, birdwatchers and families. Its canopy walkway was the second to be built in Ghana after Kakum, and the park has added a zipline, a children''s walkway and horse riding.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bunso_Canopy_walkway.jpg?width=1200', 80, 0, 0, false, '{"imageCredit":"https://commons.wikimedia.org/wiki/File:Bunso_Canopy_walkway.jpg","gallery":[],"activities":[{"id":"a1","name":"Canopy Walkway","description":"Cross the suspended walkway through the treetops. There is a lower one for young children.","duration":"45 mins","cost":25},{"id":"a2","name":"Zipline","description":"A short zipline through the forest.","duration":"20 mins","cost":20},{"id":"a3","name":"Horse Riding","description":"A guided ride on the park grounds.","duration":"20 mins","cost":10},{"id":"a4","name":"Guided Tree and Bird Walk","description":"Walk the arboretum trails with a guide who names the trees, herbs and birds.","duration":"1 hour","cost":0}],"thingsToDo":["Walk the canopy walkway","Follow the arboretum trails and learn the medicinal plants","Look for forest birds and butterflies","Picnic under the trees"],"openingHours":"Daily: 6:00 AM – 6:00 PM","entryFee":5,"safetyInfo":"Wear closed shoes; the trails are slippery after rain. Entry fees differ for Ghanaians, students and visitors from abroad and change from time to time; the prices shown are those most recently reported. Confirm at the gate.","transportOptions":[{"type":"Trotro","description":"Kumasi-bound trotro or bus from Accra (Circle or Madina); get down at Bunso junction, then a short taxi ride","duration":"2 hours"},{"type":"Taxi","description":"Shared or chartered taxi from Koforidua","duration":"1 hour"}],"nearbyDestinations":["boti-falls","aburi-botanical-gardens"],"latitude":6.2706,"longitude":-0.4614,"tags":["nature","forest","canopy walkway","botanical","birds","family","Eastern","hiking"],"bestTimeToVisit":"November to March (dry season)"}'::jsonb),
  ('kumasi-zoo', 'Kumasi Zoo', 17, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'kumasi-zoo', 'ashanti', 'wildlife', 'One of Ghana''s oldest zoos, in the heart of Kumasi, known for its primates and its huge colony of fruit bats.', 'The Kumasi Zoological Gardens sit in the middle of Kumasi, between the Kejetia terminal and the Centre for National Culture. Opened in the 1950s, it is one of the oldest zoos in Ghana and keeps primates, big cats, reptiles and birds native to West Africa. The tall trees over the zoo are also home to a very large colony of fruit bats, which fill the sky above the city at dusk.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chimpazee_at_the_Kumasi_Zoo.jpg?width=1200', 100, 0, 0, false, '{"imageCredit":"https://commons.wikimedia.org/wiki/File:Chimpazee_at_the_Kumasi_Zoo.jpg","gallery":[],"activities":[{"id":"a1","name":"Self-guided Zoo Walk","description":"See chimpanzees, monkeys, lions, crocodiles, snakes and birds at your own pace.","duration":"1.5 hours","cost":0},{"id":"a2","name":"Fruit Bat Watching","description":"Watch the bat colony roosting in the trees, and taking off towards evening.","duration":"30 mins","cost":0}],"thingsToDo":["See the chimpanzees and other primates","Look up at the fruit bat colony","Combine it with the Kumasi Cultural Centre next door"],"openingHours":"Daily: 9:00 AM – 5:00 PM","entryFee":60,"safetyInfo":"Do not feed or tease the animals, and keep children away from the enclosures. A separate fee is charged for professional photography and filming. Entry fees differ for Ghanaians, students and visitors from abroad and change from time to time; the fee shown is the adult visitor rate reported in 2026. Confirm at the gate.","transportOptions":[{"type":"Walk","description":"A few minutes on foot from the Kejetia terminal or the Kumasi Cultural Centre","duration":"10 mins"},{"type":"Ride-hailing","description":"Bolt, Uber or Yango from anywhere in Kumasi","duration":"10–30 mins"}],"nearbyDestinations":["kumasi-cultural-centre","manhyia-palace"],"latitude":6.6996,"longitude":-1.6262,"tags":["wildlife","zoo","animals","family","Kumasi","Ashanti","bats"],"bestTimeToVisit":"All year; mornings are cooler and the animals more active"}'::jsonb),
  ('accra-zoo', 'Accra Zoo', 18, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'accra-zoo', 'greater-accra', 'wildlife', 'A small zoo and primate breeding centre in the shade of Achimota Forest, in the middle of Accra.', 'Accra Zoo is set inside the Achimota Forest, the largest green space left in the capital. The zoo moved here from Kanda in the 2000s and includes an endangered primate breeding centre. It is a quiet, shaded place to see monkeys, lions, antelope, reptiles and birds without leaving the city. The enclosures are about two kilometres along a dirt road from the forest entrance where tickets are sold, so come with a car or be ready to walk.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Deer_Achimota_Forest_Zoo_Accra.jpg?width=1200', 60, 0, 0, false, '{"imageCredit":"https://commons.wikimedia.org/wiki/File:Deer_Achimota_Forest_Zoo_Accra.jpg","gallery":[],"activities":[{"id":"a1","name":"Zoo Walk","description":"Visit the primates, lions, antelope, reptiles and birds.","duration":"1.5 hours","cost":0},{"id":"a2","name":"Forest Walk","description":"Walk or jog the shaded tracks of Achimota Forest on the way to the zoo.","duration":"40 mins","cost":0}],"thingsToDo":["See the primate breeding centre","Walk under the forest canopy","Bring a picnic for the forest grounds"],"openingHours":"Daily: 9:00 AM – 4:00 PM","entryFee":20,"safetyInfo":"The zoo is roughly 2 km inside the forest from the ticket point; arrange a ride or allow 20 to 40 minutes on foot. Do not feed the animals. Entry fees differ for Ghanaians, students and visitors from abroad and change from time to time; the fee shown is the adult visitor rate most recently reported. Confirm at the gate.","transportOptions":[{"type":"Ride-hailing","description":"Bolt, Uber or Yango to the Achimota Forest entrance, Accra","duration":"20–45 mins"},{"type":"Trotro","description":"Trotro along the Achimota road to the forest gate, then walk or take a taxi in","duration":"30–60 mins"}],"nearbyDestinations":["kwame-nkrumah-memorial-park","labadi-beach"],"latitude":5.6173,"longitude":-0.2132,"tags":["wildlife","zoo","animals","forest","family","Accra","primates"],"bestTimeToVisit":"All year; go in the morning"}'::jsonb),
  ('shai-hills-resource-reserve', 'Shai Hills Resource Reserve', 19, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'shai-hills-resource-reserve', 'greater-accra', 'wildlife', 'Savannah, rocky hills, baboons, antelope and historic caves, an hour from Accra.', 'Shai Hills is the closest wildlife reserve to Accra, about 50 kilometres to the north-east on the road to Akosombo. Open savannah surrounds a chain of rocky hills where olive baboons, kob, bushbuck, green monkeys and well over a hundred bird species live. The hills hold caves that were home to the Shai people until the 1890s; guides lead visitors up to them, including the bat-filled Sayu Cave, for wide views over the Accra Plains.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shai_Hills,_Shai-Osudoku_(P1100110).jpg?width=1200', 150, 0, 0, false, '{"imageCredit":"https://commons.wikimedia.org/wiki/File:Shai_Hills,_Shai-Osudoku_(P1100110).jpg","gallery":[],"activities":[{"id":"a1","name":"Guided Game Drive","description":"Drive the reserve tracks with a ranger to find kob, baboons and birds. Bring your own vehicle.","duration":"2 hours","cost":0},{"id":"a2","name":"Cave Hike","description":"Climb with a guide to the caves once lived in by the Shai people.","duration":"2 hours","cost":0},{"id":"a3","name":"Bird Watching","description":"More than 150 species have been recorded in the reserve.","duration":"2 hours","cost":0}],"thingsToDo":["Meet the baboons at the gate","Hike to Sayu Cave and its bats","Look for kob and bushbuck on the plains","Take in the view from the hilltops"],"openingHours":"Daily: 8:00 AM – 5:00 PM","entryFee":50,"safetyInfo":"Go with a guide for the caves and hikes, carry water and wear sturdy shoes. Keep food out of sight of the baboons. Separate charges apply for vehicles and guides. Entry fees differ for Ghanaians, students and visitors from abroad and change from time to time; the fee shown is the adult visitor rate reported in 2026. Confirm at the gate.","transportOptions":[{"type":"Trotro","description":"Trotro from Accra (Madina or Tema) towards Akosombo or Ho; get down at the Shai Hills gate after Afienya","duration":"1.5 hours"},{"type":"Taxi","description":"Chartered taxi or ride-hailing from Accra, kept for the game drive","duration":"1 hour"}],"nearbyDestinations":["aburi-botanical-gardens","ada-foah","lake-volta"],"latitude":5.9,"longitude":0.05,"tags":["wildlife","safari","baboons","caves","hiking","birds","nature","history","Accra"],"bestTimeToVisit":"November to April (dry season)"}'::jsonb),
  ('larabanga-mosque', 'Larabanga Mosque', 20, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'larabanga-mosque', 'savannah', 'religious', 'Ghana''s most famous mud-built mosque, dated by tradition to 1421, at the gateway to Mole National Park.', 'The whitewashed mud-and-stick mosque at Larabanga is the best-known example of Sudano-Sahelian architecture in Ghana and is widely described as the oldest mosque in the country, with tradition dating it to 1421. Timber poles brace its tapering buttresses and two pyramidal towers. It is still a place of worship for the village, so non-Muslims view it from outside. A short way off is the Mystic Stone, which local tradition says returned to its place each time road builders moved it. Larabanga is on the road into Mole National Park, and the two are usually visited together.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Larabanga_Mosque_Ghana.jpg?width=1200', 80, 0, 0, false, '{"imageCredit":"https://commons.wikimedia.org/wiki/File:Larabanga_Mosque_Ghana.jpg","gallery":[],"activities":[{"id":"a1","name":"Guided Visit to the Mosque","description":"A community guide tells the story of the mosque and its founding. Non-Muslims stay outside.","duration":"45 mins","cost":0},{"id":"a2","name":"Mystic Stone","description":"See the stone that tradition says could not be moved from the roadside.","duration":"20 mins","cost":0}],"thingsToDo":["Hear the founding story from a community guide","Photograph the mosque from outside","Visit the Mystic Stone","Continue to Mole National Park"],"openingHours":"Daytime visits; avoid prayer times","entryFee":50,"safetyInfo":"Dress modestly, ask before taking photographs of people, and agree the fee with the official community guides before the tour. Non-Muslims may not enter the mosque. Reported fees range from 10 to 50 cedis depending on the visitor, with a tip expected for the guide; the fee shown is the upper figure.","transportOptions":[{"type":"Bus","description":"Bus or trotro from Tamale to Damongo, then a shared taxi on to Larabanga","duration":"3 hours"},{"type":"Taxi","description":"Shared taxi or motorbike taxi from Damongo, or from the Mole National Park gate nearby","duration":"20 mins"}],"nearbyDestinations":["mole-national-park"],"latitude":9.2203,"longitude":-1.8603,"tags":["mosque","religious","history","architecture","heritage","culture","Savannah","north"],"bestTimeToVisit":"November to March (dry season)"}'::jsonb)
insert into public.events (id, name, position, created_at, updated_at, status, archived_at, slug, region_id, category, location, start_date, end_date, is_free, ticket_price, short_description, description, image_url, featured, details) values
  ('homowo-festival-2026', 'Homowo Festival', 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'homowo-festival-2026', 'greater-accra', 'traditional', 'Accra', '2026-08-01', '2026-08-31', true, null, 'The Ga people''s vibrant "hooting at hunger" harvest festival — a joyful celebration of abundance, family, and ancestral memory.', 'Homowo, meaning "to hoot at hunger" in the Ga language, is one of Ghana''s most beloved annual harvest festivals celebrated by the Ga people of Greater Accra. The festival commemorates a historic famine that the Ga people survived, and celebrates the subsequent abundant harvest. Families gather for communal feasts of palm nut soup and kpokpoi (a traditional dish), libations are poured to ancestors, and traditional drumming and dance fill the streets. The festival strengthens family bonds and cultural identity.', 'https://images.unsplash.com/photo-1589825743636-23a879d4b8e2?w=800&q=80', true, '{"venue":"Various locations across Accra","activities":["Traditional drumming and dance performances","Communal feasts of kpokpoi and palm nut soup","Libation ceremonies for ancestors","Processions through Ga communities","Cultural exhibitions"],"transportInfo":"Easily accessible from anywhere in Accra via trotro or taxi.","relatedDestinations":["kwame-nkrumah-memorial-park","labadi-beach"],"tags":["Ga","harvest","traditional","food","culture","Accra","family"]}'::jsonb),
  ('chale-wote-2026', 'Chale Wote Street Art Festival', 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'chale-wote-2026', 'greater-accra', 'art', 'James Town, Accra', '2026-08-21', '2026-08-23', true, null, 'Accra''s electrifying annual street art festival — transforming James Town into a canvas of colour, music, performance, and Pan-African creativity.', 'Chale Wote ("friend, let''s go" in Ga) is Accra''s most vibrant annual street art festival, transforming the historic James Town neighbourhood into an open-air gallery. The festival features murals, installations, live music, spoken word, performance art, fashion, and film screenings by African artists. It celebrates the creativity, diversity, and resilience of African urban culture and draws visitors from across the continent and the world.', 'https://images.unsplash.com/photo-1565373677928-80cf5b789d2e?w=800&q=80', true, '{"venue":"James Town, Accra (outdoor streets and spaces)","activities":["Live mural painting by African artists","Music and DJ performances","Spoken word and poetry slams","Afrobeats and highlife concerts","Fashion showcases","Film screenings","Food and craft markets"],"transportInfo":"James Town is in central Accra. Accessible via trotro or taxi.","relatedDestinations":["kwame-nkrumah-memorial-park","labadi-beach"],"tags":["art","street art","music","culture","festival","Accra","James Town"],"website":"https://challewote.com"}'::jsonb),
  ('panafest-2026', 'PANAFEST', 2, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'panafest-2026', 'central', 'cultural', 'Cape Coast & Elmina', '2026-07-25', '2026-08-01', false, 200, 'A powerful biennial Pan-African festival blending theatre, music, heritage visits, and deep reflection on African history and identity.', 'PANAFEST (Pan African Historical Theatre Festival) is a biennial festival held at Cape Coast and Elmina that celebrates Pan-African culture, history, and the diaspora. The festival includes theatre performances, seminars, music, durbars, and visits to the historic slave castles — creating a powerful space for reflection on African identity, the transatlantic slave trade, and African unity. It draws African diaspora communities from the Americas, Caribbean, and Europe to reconnect with their ancestral homeland.', 'https://images.unsplash.com/photo-1575986767340-5d17ae767ab0?w=800&q=80', true, '{"venue":"Cape Coast Castle, Elmina Castle, and surrounding venues","activities":["Theatre performances and dramatic re-enactments","Academic seminars on Pan-Africanism","Music concerts featuring African artists","Royal durbars and cultural processions","Guided heritage tours of the slave castles","Diaspora homecoming ceremonies"],"transportInfo":"Cape Coast is 3 hours from Accra by STC bus (₵30-50) or by shared taxi.","relatedDestinations":["cape-coast-castle","elmina-castle","kakum-national-park"],"tags":["Pan-African","heritage","theatre","culture","diaspora","Cape Coast","history"]}'::jsonb),
  ('hogbetsotso-2026', 'Hogbetsotso Festival', 3, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'hogbetsotso-2026', 'volta', 'traditional', 'Anloga, Volta Region', '2026-11-07', '2026-11-08', true, null, 'The spectacular Anlo Ewe migration festival — witness breathtaking durbars, traditional Agbadza dance, and centuries of living culture.', 'Hogbetsotso is the annual festival of the Anlo Ewe people of the Volta Region, celebrating their migration from Notsie (in present-day Togo) to their current homeland centuries ago. The festival features spectacular durbar processions with chiefs in palanquins, colourful traditional attire, energetic traditional dance (Agbadza), drumming, libation ceremonies, and the firing of muskets. It is one of Ghana''s most visually spectacular traditional festivals.', 'https://images.unsplash.com/photo-1564419320461-6870880221ad?w=800&q=80', false, '{"venue":"Anloga, Keta District","activities":["Grand durbar of chiefs and queen mothers","Traditional Agbadza dance performances","Musket firing ceremonies","Cultural processions in traditional attire","Communal feasts and celebrations"],"transportInfo":"From Accra, take a bus to Aflao (about 3 hours), then trotro towards Anloga.","relatedDestinations":["wli-waterfalls","lake-volta"],"tags":["Ewe","traditional","festival","Volta","dance","cultural","durbar"]}'::jsonb),
  ('aboakyir-2026', 'Aboakyir Festival', 4, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'aboakyir-2026', 'central', 'traditional', 'Winneba, Central Region', '2026-05-02', '2026-05-03', true, null, 'One of Ghana''s oldest festivals — two warrior companies race to capture a live deer bare-handed in this thrilling Central Region tradition.', 'Aboakyir — the deer hunting festival of the Efutu people of Winneba in the Central Region — is one of Ghana''s oldest and most thrilling traditional festivals. Two rival Asafo companies (warrior groups) compete to be first to capture a live deer with their bare hands and present it to the chief. The successful group earns great honour and bragging rights for the entire year. The festival is accompanied by colourful processions, traditional music, and elaborate ceremonies.', 'https://images.unsplash.com/photo-1582555172866-f73bb12a2ab3?w=800&q=80', false, '{"venue":"Winneba town","activities":["Live deer hunting competition between Asafo companies","Traditional processions with chiefs","Drumming and singing","Cultural displays","Visit the nearby Potsin area"],"transportInfo":"Winneba is about 65 km west of Accra. Take a trotro from Kasoa (₵15-25) or a bus from Accra.","relatedDestinations":["cape-coast-castle","kakum-national-park"],"tags":["traditional","hunting","Efutu","Central","competition","culture","Winneba"]}'::jsonb),
  ('ghana-jollof-festival-2026', 'Ghana Jollof Festival', 5, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ghana-jollof-festival-2026', 'greater-accra', 'food', 'Accra', '2026-10-16', '2026-10-18', false, 80, 'A delicious celebration of Ghana''s rich food culture — taste jollof rice showdowns, traditional dishes, street food, and live cooking demos.', 'The Ghana Jollof Festival is a colourful food and culture festival celebrating Ghana''s rich culinary heritage and settling, once and for all, the friendly West African debate about whose jollof rice reigns supreme. Beyond jollof rice, the festival showcases traditional Ghanaian dishes, street food, international cuisine, live cooking demonstrations, music, and cultural entertainment. A joyful celebration of food and community.', 'https://images.unsplash.com/photo-1589825743636-23a879d4b8e2?w=800&q=80', true, '{"venue":"Accra Sports Stadium grounds","activities":["Jollof rice cooking competition","Traditional food tastings","Chef demonstrations and workshops","Music and entertainment","Children''s food activities"],"transportInfo":"Accra Sports Stadium is in the Accra centre. Take any trotro or taxi towards the stadium.","relatedDestinations":["kwame-nkrumah-memorial-park","labadi-beach"],"tags":["food","jollof","Ghanaian cuisine","culture","cooking","festival","Accra"]}'::jsonb),
  ('damba-festival-2026', 'Damba Festival', 6, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'damba-festival-2026', 'northern', 'religious', 'Tamale, Northern Region', '2026-11-15', '2026-11-17', true, null, 'A magnificent blend of Islamic faith and northern Ghanaian tradition — spectacular horse parades, royal durbars, and vibrant cultural performances.', 'Damba is an Islamic festival celebrated by several northern Ghanaian peoples — including the Dagomba, Gonjas, and Mamprusis — to commemorate the birth and naming of the Prophet Muhammad (Mawlid). The festival features magnificent horse parades (the Damba Festival is famous for its horse-riding displays), drumming, dancing, the chiefs giving speeches from horseback, and communal celebrations. It is a beautiful blend of Islamic faith and traditional northern Ghanaian culture.', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=800&q=80', false, '{"venue":"Tamale (Dagbon Traditional Area)","activities":["Traditional horse parades and riding displays","Royal durbar of Dagomba chiefs","Drumming and dancing","Islamic prayers and ceremonies","Cultural processions"],"transportInfo":"Tamale is accessible by STC bus from Accra (9–10 hours, ₵100–150) or by domestic flight.","relatedDestinations":["mole-national-park"],"tags":["Islamic","Northern","horses","cultural","Dagomba","Tamale","traditional"]}'::jsonb),
  ('bakatue-festival-2026', 'Bakatue Festival', 7, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bakatue-festival-2026', 'central', 'traditional', 'Elmina, Central Region', '2026-07-04', '2026-07-05', true, null, 'Elmina''s colourful lagoon-opening festival — a joyful ceremony blessing the start of the fishing season with canoe processions and royal durbars.', 'Bakatue, meaning "the opening of the lagoon", is the traditional festival of the people of Elmina in the Central Region marking the start of the fishing season on the Benya Lagoon. The festival includes a canoe procession on the lagoon, libations to the gods of the sea, casting of nets to mark the beginning of fishing, colourful durbars of chiefs, and cultural performances. It is a vibrant celebration of the fishing community''s livelihood and spiritual heritage.', 'https://images.unsplash.com/photo-1575986767340-5d17ae767ab0?w=800&q=80', false, '{"venue":"Benya Lagoon, Elmina","activities":["Canoe processions on the Benya Lagoon","Libation ceremonies to the sea gods","Traditional fishing ceremony (casting of nets)","Durbar of chiefs","Cultural music and dance"],"transportInfo":"Elmina is 15 km west of Cape Coast. Take trotro from Cape Coast (₵5-10).","relatedDestinations":["elmina-castle","cape-coast-castle"],"tags":["fishing","Elmina","lagoon","Central","traditional","canoe","coastal"]}'::jsonb),
  ('asafotufiam-2026', 'Asafotufiam Festival', 8, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'asafotufiam-2026', 'greater-accra', 'traditional', 'Ada Foah, Greater Accra', '2026-08-04', '2026-08-08', true, null, 'The Ada people''s bold celebration of military victory — spectacular warrior processions, musket fire, and durbars at the stunning Ada Foah lagoon.', 'Asafotufiam is the annual festival of the Ada people of the Greater Accra Region, held at Ada Foah. The festival commemorates the victory of the Ada people over external aggressors and celebrates their resilience, bravery, and unity. It features spectacular military-style Asafo company displays, musket firing, traditional dances, colourful processions, and durbars of paramount chiefs. The backdrop of the beautiful Ada lagoon adds to the spectacular setting.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', false, '{"venue":"Ada Foah","activities":["Asafo company military displays","Musket firing","Traditional Ada dance performances","Durbar of Ada paramount chiefs","Canoe processions"],"transportInfo":"From Accra, take trotro from Tema station to Ada junction then shared taxi to Ada Foah.","relatedDestinations":["ada-foah","labadi-beach"],"tags":["Ada","traditional","military","festival","Greater Accra","canoe","warrior"]}'::jsonb),
  ('ghana-film-festival-2026', 'Ghana International Film Festival', 9, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ghana-film-festival-2026', 'greater-accra', 'art', 'Accra', '2026-10-08', '2026-10-13', false, 50, 'Ghana''s premier cinema event — celebrating African storytelling with screenings, masterclasses, and awards across Accra''s venues.', 'The Ghana International Film Festival is an annual celebration of African and international cinema, showcasing feature films, documentaries, and short films. The festival provides a platform for Ghanaian and African filmmakers, hosts masterclasses with industry professionals, and engages film lovers across Accra. Screenings take place at multiple venues including outdoor settings, and the event culminates in a prestigious awards ceremony.', 'https://images.unsplash.com/photo-1565373677928-80cf5b789d2e?w=800&q=80', false, '{"venue":"Various cinemas and venues across Accra","activities":["Film screenings (features, documentaries, shorts)","Director Q&A sessions","Filmmaking masterclasses","Networking events for industry professionals","Opening and closing galas","Awards ceremony"],"transportInfo":"Various venues across Accra — check individual venue locations for transport options.","relatedDestinations":["kwame-nkrumah-memorial-park"],"tags":["film","cinema","art","African","storytelling","Accra","entertainment"]}'::jsonb),
  ('choral-festival-kumasi-2026', 'Kumasi Choral Festival', 10, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'choral-festival-kumasi-2026', 'ashanti', 'music', 'Kumasi', '2026-10-23', '2026-10-25', false, 40, 'Ghana''s premier choral music gathering — choirs from across the country converge on Kumasi for an unforgettable celebration of voice and harmony.', 'The Kumasi Choral Festival is a prestigious annual celebration of Ghanaian choral music held in Kumasi, Ghana''s cultural capital. The festival brings together choirs from across Ghana — church choirs, school choirs, and community ensembles — to perform a rich repertoire of classical choral works, Ghanaian folk songs, and gospel music. It is one of the most beloved musical events in Ashanti Region, drawing thousands of music lovers.', 'https://images.unsplash.com/photo-1565373677928-80cf5b789d2e?w=800&q=80', false, '{"venue":"Kumasi Cultural Centre and surrounding venues","activities":["Choral competitions between visiting choirs","Gala concerts featuring top Ghanaian choirs","Youth choir showcases","Music workshops and masterclasses","Awards ceremony"],"transportInfo":"Kumasi is accessible by STC bus from Accra (4.5 hours, ₵80-120) or domestic flight.","relatedDestinations":["manhyia-palace","kumasi-cultural-centre"],"tags":["music","choral","Kumasi","Ashanti","gospel","competition","performance"]}'::jsonb),
  ('kundum-festival-2026', 'Kundum Festival', 11, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'kundum-festival-2026', 'western', 'traditional', 'Sekondi-Takoradi area, Western Region', '2026-09-15', '2026-10-15', true, null, 'An ancient harvest purification festival of the Ahanta and Nzema — elaborate rites, yam celebrations, and ancestral music across the Western Region.', 'Kundum is an ancient harvest and purification festival celebrated by the Ahanta and Nzema peoples of Ghana''s Western Region. The festival is marked by elaborate purification rites, communal celebrations of the yam harvest, traditional music and dance, libations to ancestral spirits, and colourful processions. Each town celebrates Kundum at different times between August and October, creating a rolling series of festivals throughout the region.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', false, '{"venue":"Various towns in the Western Region","activities":["Traditional purification rites","Yam harvest celebrations","Traditional music and dance","Libation ceremonies","Communal feasts"],"transportInfo":"Sekondi-Takoradi is 250 km west of Accra. STC buses run daily (₵60-90, 4-5 hours).","relatedDestinations":["nzulezu-stilt-village"],"tags":["Ahanta","Nzema","harvest","Western","traditional","purification","yam"]}'::jsonb)
insert into public.festivals (id, name, position, created_at, updated_at, status, archived_at, region_id, category, town, ethnic_group, month, description, image_url, completeness, featured, details) values
  ('homowo', 'Homowo Festival', 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'greater-accra', 'harvest', 'Accra (Ga Mashie), Osu, La, Teshie, Nungua, Tema', 'Ga', 'August – September', 'Homowo, "hooting at hunger" in the Ga language, is the harvest festival of the Ga people. It recalls a famine in Ga history and the plentiful harvest that ended it.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Accra_Homowo_um1900_300dpi.jpg?width=1200', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Ga State","usualDate":"Each Ga town celebrates on its own date within the season","duration":"Season runs from planting in May to the feast in August/September","historicalSignificance":"Tradition holds that the Ga suffered famine during their migration and settlement. When the rains returned and the harvest was good, they jeered at the hunger that had afflicted them. The custom is tied to the Ga traditional calendar and the Lante Dzan We people of the Asere quarter.","culturalSignificance":"A time of remembrance and thanksgiving that honours Ga ancestors and brings families home. The Ga towns (Ga Mashie, Osu, La, Teshie, Nungua and Tema) each hold their own Homowo, so the celebrations move from town to town.","activities":["Planting of millet before the rains in May","Sprinkling of kpokpoi (a traditional corn meal) by chiefs and family heads","Sacrifices, prayers and libation","Drumming, singing and dancing"],"attractionsNearby":["Jamestown Lighthouse","Osu Castle","Labadi Beach","Kwame Nkrumah Memorial Park"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Accra_Homowo_um1900_300dpi.jpg","sources":["https://en.wikipedia.org/wiki/Homowo","https://ghanaculture.gov.gh/homowo-festival-august-september/","https://ghanaculture.gov.gh/greater-accra-region/"],"notes":"Teshie, Nungua, Tema and Ga Mashie Homowo are the same festival held on different dates by each town, so they are recorded here as one entry. The photo is a historical image from around 1900."}'::jsonb),
  ('asafotufiam', 'Asafotufiam Festival', 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'greater-accra', 'war-commemoration', 'Ada (Big Ada)', 'Dangme (Ada)', 'August', 'A warriors'' festival of the chiefs and people of Ada. The name comes from the Dangme "Asafotufiami", meaning the divisional firing of musketry.', '', 'detailed', false, '{"alternateNames":["Asafotufiami"],"otherRegions":[],"traditionalArea":"Ada","usualDate":"First week of August","duration":"","historicalSignificance":"Celebrated in remembrance of the ancestors who fought in the wars that secured the Ada settlement.","culturalSignificance":"Honours the bravery of Ada''s warriors; the asafo companies re-enact battle by firing muskets, and the Kpatsa dance is performed to entertain the chief and people.","activities":["Firing of muskets by the asafo companies","Kpatsa dance","Drumming and dancing","Traditional military displays"],"attractionsNearby":["Ada Foah and the Volta estuary","Songor Lagoon"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Asafotufiam_Festival","https://ghanaculture.gov.gh/aboakyer-festival3/","https://ghanaculture.gov.gh/greater-accra-region/"],"notes":"The NCC festival page is titled \"July – August\" but its month field says May; Wikipedia gives the first week of August."}'::jsonb),
  ('kpledjoo', 'Kpledjoo Festival', 2, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'greater-accra', 'harvest', 'Tema', 'Ga', 'March – April', 'A festival of the chiefs and people of Tema that marks the start of the farming season, especially the planting of maize. The name joins "Kple", a traditional Ga religion, and "Joo", dance.', '', 'detailed', false, '{"alternateNames":["Kplejoo"],"otherRegions":[],"traditionalArea":"Tema","usualDate":"Late March or the first week of April","duration":"","historicalSignificance":"Celebrated for generations and older than the colonial period, it is rooted in the traditional religion and farming practices of the Tema people.","culturalSignificance":"Where Homowo celebrates the harvest, Kpledjoo is the spiritual preparation for farming. Priests and priestesses invoke blessings for rain, fertility, peace and a good harvest, in rites linked to the sacred Sakumo Lagoon.","activities":["Sacred rites by traditional priests and priestesses","Kple music, drumming and dance","Communal ceremonies"],"attractionsNearby":["Sakumo Lagoon","Tema Harbour","Greenwich Meridian marker, Tema"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Kpledjoo_Festival"],"notes":""}'::jsonb),
  ('ngmayem-shai', 'Ngmayem Festival (Shai)', 3, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'greater-accra', 'harvest', 'Dodowa (Shai Osudoku District)', 'Dangme (Shai)', 'October', 'Celebrated by the chiefs and people of the Shai Osudoku area. It brings citizens at home and abroad together to plan development.', '', 'basic', false, '{"alternateNames":["Gmayem","Mgmayem"],"otherRegions":[],"traditionalArea":"Shai","usualDate":"October, set by the traditional calendar","duration":"","historicalSignificance":"Held in commemoration of the end of a famine that afflicted the people centuries ago.","culturalSignificance":"All funerals in the traditional area are suspended until the festival is over.","activities":[],"attractionsNearby":["Shai Hills Resource Reserve","Dodowa Forest"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Gmayem_Festival"],"notes":""}'::jsonb),
  ('chale-wote', 'Chale Wote Street Art Festival', 4, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'greater-accra', 'arts', 'Jamestown, Accra', '', 'August', 'An annual street art festival organised by ACCRA [dot] ALT. "Chale Wote" means "friend, let''s go" in Ga and is also the name of a common flip-flop.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chale_Wote_Street_Art_Festival_10.jpg?width=1200', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"","usualDate":"Mid to late August, around a week after Homowo","duration":"About one week since 2016 (one or two days in earlier editions)","historicalSignificance":"First held in 2011 in historic Jamestown. From 2016 it grew into a week-long event spreading to other art spaces in Accra.","culturalSignificance":"Brings local and international artists and audiences together in open public space.","activities":["Street painting and graffiti murals","Photography and interactive art installations","Theatre and spoken word","Live music performances","Film shows"],"attractionsNearby":["Jamestown Lighthouse","Ussher Fort","James Fort","Brazil House"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Chale_Wote_Street_Art_Festival_10.jpg","sources":["https://en.wikipedia.org/wiki/Chale_Wote_Street_Art_Festival"],"notes":""}'::jsonb),
  ('aboakyer', 'Aboakyer Festival', 5, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'hunting', 'Winneba', 'Effutu', 'May', 'A hunting festival of the people of Winneba. Aboakyer means "hunting for game or animal" in Fante.', '', 'detailed', false, '{"alternateNames":["Aboakyir","Deer Hunt Festival"],"otherRegions":[],"traditionalArea":"Effutu (Winneba)","usualDate":"First Saturday in May","duration":"","historicalSignificance":"Instituted to commemorate the migration of the Simpafo (the people of Winneba) to the central coast. Their god, later settled at Penkye and known as Penkye Otu, is said to have first demanded a human sacrifice from the royal family, then a wild cat caught alive, which cost many lives, and finally accepted a deer.","culturalSignificance":"One of the best-known festivals in Ghana and a major draw for visitors.","activities":["Hunt for a live animal","Presentation of the catch to the chief","Sacrifice at the Penkye Otu shrine","Durbar, drumming and dancing"],"attractionsNearby":["Winneba beaches","Muni-Pomadze Ramsar Site"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Aboakyer_festival","https://ghanaculture.gov.gh/aboakyer-festival/","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('fetu-afahye', 'Fetu Afahye', 6, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'purification', 'Cape Coast', 'Fante (Oguaa)', 'September', 'The festival of the chiefs and people of Cape Coast, named after the 17th-century Fetu (Effutu) kingdom inland of the town.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Oguaa (Cape Coast)","usualDate":"First Saturday in September; preparations begin in the last week of August","duration":"","historicalSignificance":"Kept in remembrance of a historic disease outbreak and to keep the town clean so that no epidemic returns. The colonial administration once banned it as \"Black Christmas\"; it later resumed after sustained effort by leaders of the Oguaa Traditional Area.","culturalSignificance":"Marks a good harvest from the sea and gives thanks to the 77 gods of Oguaa. It also serves as the calendar for the farming seasons, known as \"Afehyia\", a loop of seasons.","activities":["Purification rites","Offering of mashed yam to the gods","Grand processions","Durbar of chiefs","Drumming and dancing"],"attractionsNearby":["Cape Coast Castle","Fosu Lagoon","Kakum National Park","Fort William, Cape Coast"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Fetu_Afahye","https://ghanaculture.gov.gh/fetu-afahye-festival-september/","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('bakatue', 'Bakatue Festival', 7, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'fishing', 'Elmina', 'Fante (Edina)', 'July', 'Marks the beginning of the fishing season in Elmina. Bakatue is Fante for "draining of a lagoon".', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bakatue_2016_001_B001.jpg?width=1200', 'detailed', false, '{"alternateNames":["Edina Bakatue"],"otherRegions":[],"traditionalArea":"Edina (Elmina)","usualDate":"First Tuesday in July","duration":"Two days (the first Monday and Tuesday of July)","historicalSignificance":"Dutch records show the festival existed at least as far back as 1847, and Governor Cornelis Nagtglas mentioned it in an 1860 report. It is also said to commemorate the founding of Elmina.","culturalSignificance":"Thanks and prayers are offered to the gods for a good fishing year.","activities":["Customary rites on the Monday","Libation and symbolic offerings at the Benya Lagoon","Grand durbar of chiefs","Traditional drumming and cultural dances"],"attractionsNearby":["Elmina Castle (St George''s Castle)","Fort St Jago","Benya Lagoon"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Bakatue_2016_001_B001.jpg","sources":["https://en.wikipedia.org/wiki/Bakatue_Festival","https://ghanaculture.gov.gh/aboakyer-festival2/","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('edina-bronya', 'Edina Bronya Festival', 8, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'heritage', 'Elmina', 'Fante (Edina)', 'January', 'A festival of the chiefs and people of Elmina, described as a "novel Christmas" dating from the Dutch colonial era.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Edina (Elmina)","usualDate":"First Thursday of January","duration":"","historicalSignificance":"It coincides with a Dutch festival and signifies the long relationship between the people of Elmina and the Dutch.","culturalSignificance":"A time for families and friends to gather, eat and make merry at the turn of the year.","activities":["Midnight gunshots fired by the Paramount Chief on the eve","Paramount Chief carried in a palanquin","Slaughter of sheep in front of Elmina Castle","Family gatherings and feasting"],"attractionsNearby":["Elmina Castle (St George''s Castle)","Fort St Jago"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Edina_Bronya_Festival","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('okyir', 'Okyir Festival', 9, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'harvest', 'Anomabo', 'Fante', 'October', 'An annual thanksgiving festival of the Fante town of Anomabo, held to give thanks for the harvest and to honour the ancestors.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Anomabo","usualDate":"Second week of October","duration":"One week","historicalSignificance":"","culturalSignificance":"\"Okyir\" means \"abomination\": the festival is used to campaign against social vices such as poor sanitation, teenage pregnancy, greed and injustice, and to renew ties among families and citizens of Anomabo everywhere.","activities":["Traditional ceremonies","Processions of chiefs in regalia","Drumming and dancing","Cultural displays"],"attractionsNearby":["Fort William, Anomabo","Anomabo Beach"],"imageCredit":"","sources":["https://ghanaculture.gov.gh/okyir-festival-october/","https://gna.org.gh/2022/10/anomabo-climaxes-okyir-festival-in-glitz/","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('akwambo', 'Akwambo Festival', 10, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'migration', '', 'Fante (Agona and Gomoa)', 'August', 'Akwambo, literally "path-clearing", is celebrated by the chiefs and people of the Agona and Gomoa areas.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Agona and Gomoa","usualDate":"","duration":"Often one week","historicalSignificance":"First observed by migrant ancestors whose first task on arriving in a new place was to clear paths to rivers, farms and communal places. It remembers the journey and arrival of the original settlers of Gyinankoma, Ekrawfo, Atakwaa and Otabenadze.","culturalSignificance":"A celebration of kinship, unity and shared heritage, and a time for family and community reunions.","activities":["Path clearing","Durbar","Music and dance performances","Football matches","Street parades"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Akwambo_festival","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('odambea', 'Odambea Festival', 11, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'migration', 'Saltpond', 'Fante (Nkusukum)', 'August', 'Celebrated by the chiefs and people of the Nkusukum Traditional Area. Odambea means "fortified link".', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Nkusukum","usualDate":"End of August","duration":"","historicalSignificance":"Commemorates the migration of the Nkusukum people from Techiman to their present home.","culturalSignificance":"The festival re-enacts the ancient lifestyles of the people of the area.","activities":["Re-enactment of ancient ways of life","Durbar of chiefs","Drumming and dancing","Sharing of food and drink with visitors"],"attractionsNearby":["Fort Amsterdam, Abandze","Saltpond beaches"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Odambea_Festival","https://ghanaculture.gov.gh/central-region/"],"notes":"Wikipedia adds that it is also celebrated by the people of Anomabo."}'::jsonb),
  ('awubia', 'Awubia Festival', 12, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'harvest', 'Awutu Bereku', 'Awutu', 'August – September', 'A festival held to hoot at hunger and welcome a bumper harvest of grain. "Awu" means grain and "Bia" means reaping, so Awubia is the harvesting of grain.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Awutu","usualDate":"","duration":"One week","historicalSignificance":"Commemorates King Wyettey I, who is said to have brought the people to settle at Awutu in the 14th century and to have sown grain near the Pooyoo Shrine that matured within three weeks for the first Awubia.","culturalSignificance":"Thanks are offered to the gods and ancestors, and the people mourn those who died during the year before making merry.","activities":["Communal feast of dishes made from the new harvest","Remembrance of the departed","Durbar of chiefs"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Awubia_Festival","https://www.graphic.com.gh/news/general-news/the-awubia-festival-a-celebration-of-history-and-identity.html","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('ahobaa-kese', 'Abeadze Ahobaa Kese Festival', 13, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'ancestral', 'Abeadze Dominase', 'Fante (Abeadze)', 'June', 'A week-long celebration of the Abeadze Traditional Area, with a day set aside for traditional rituals and special stool rites.', '', 'detailed', false, '{"alternateNames":["Ahobaa"],"otherRegions":[],"traditionalArea":"Abeadze","usualDate":"Begins on the twelfth Tuesday after the launch of \"Abeadzeman Ogya\"","duration":"One week","historicalSignificance":"Held in remembrance of Egya Ahor, who gave his life so that his people could be saved from a plague that struck them after their migration from Techiman.","culturalSignificance":"Celebrated to obtain the blessing of the ancestors.","activities":["Traditional rituals and stool rites","Traditional drumming and dancing","Durbar of chiefs"],"attractionsNearby":[],"imageCredit":"","sources":["https://visitghana.com/abeadze-ahobaa-kese-festival/","https://en.wikipedia.org/wiki/Ahobaa_Festival","https://ghanaculture.gov.gh/central-region/"],"notes":"An Ahobaa festival is also celebrated in June at Enyan-Kakraba near Saltpond. No source was found for an Ahobaa festival in the Western Region."}'::jsonb),
  ('nyeyi-tuakron', 'Komenda Nyeyi Festival', 14, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'ancestral', 'Komenda', 'Fante (Komenda)', 'September', 'Celebrated by the chief and people of Komenda in the Komenda-Edina-Eguafo-Abrem Municipality.', '', 'basic', false, '{"alternateNames":["Nyeyi and Tuakrom","Komendaman Nyeyi"],"otherRegions":[],"traditionalArea":"Komenda","usualDate":"Second Saturday of September","duration":"","historicalSignificance":"Held in honour of the departed heroes and heroines of Komenda for their contribution to the traditional area.","culturalSignificance":"Strengthens the bond between the people and their ancestors.","activities":[],"attractionsNearby":["Fort Komenda (English Fort)","Fort Vredenburg"],"imageCredit":"","sources":["https://www.modernghana.com/news/698455/komenda-launches-nyeyi-festival-for-september.html","https://ghanaculture.gov.gh/central-region/"],"notes":"The NCC lists \"Nyeyi and Tuakrom\" together; how the two names relate was not explained by any source found."}'::jsonb),
  ('odunkwaa', 'Odunkwaa Festival', 15, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'heritage', 'Abakrampa and Abura Dunkwa', 'Fante (Abura)', 'April', 'A week-long celebration with two venues: Abakrampa, the seat of the traditional area, and Abura Dunkwa, the administrative capital.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Abura","usualDate":"Starts on Easter Monday and climaxes on the Saturday","duration":"One week","historicalSignificance":"The Odum tree is regarded as sacred and is believed to have protected the people from attack during their wars.","culturalSignificance":"Chiefs converge at the palace to pay homage to the Paramount Chief.","activities":["Fencing of the sacred Odum tree","Durbar of chiefs","Drumming and dancing"],"attractionsNearby":[],"imageCredit":"","sources":["https://ghanaculture.gov.gh/sample-april-festival-april/"],"notes":"Your list also placed Odunkwaa under Ashanti; the NCC locates it only at Abakrampa and Abura Dunkwa in the Central Region."}'::jsonb),
  ('panafest', 'PANAFEST', 16, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'heritage', 'Cape Coast and Elmina', '', 'July – August', 'A cultural event for Africans and people of African descent, promoting unity, Pan-Africanism and the development of the continent.', '', 'detailed', false, '{"alternateNames":["Pan African Historical Theatre Project"],"otherRegions":[],"traditionalArea":"","usualDate":"Every two years","duration":"","historicalSignificance":"Proposed by Efua Sutherland in the mid-1980s and first held in 1992, it confronts the legacy of the slave trade at the castles and forts along Ghana''s coast.","culturalSignificance":"Brings Africans on the continent and in the diaspora together around the issues raised by slavery.","activities":["Theatre and drama","Music and poetry","Durbar of chiefs","Tours of the slave castle dungeons"],"attractionsNearby":["Cape Coast Castle","Elmina Castle (St George''s Castle)","Assin Manso Slave River Site"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Panafest","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('emancipation-day', 'Emancipation Day', 17, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'central', 'heritage', 'Assin Manso', '', 'August', 'Ghana''s commemoration of the abolition of slavery, with events in Accra, Cape Coast and Elmina and a climax at Assin Manso.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":["Greater Accra"],"traditionalArea":"","usualDate":"1 August","duration":"","historicalSignificance":"Introduced in 1998, when Ghana became the first African nation to mark Emancipation Day. Assin Manso is where enslaved Africans took their \"last bath\" before being marched to the coast; remains repatriated from the diaspora were reburied there in 1998.","culturalSignificance":"A day of remembrance linking Ghana with the African diaspora.","activities":["Emancipation Day durbar at Assin Manso","Wreath laying at the graves of the returned ancestors","Visit to Nonko Nsuo, the \"last bath\" river"],"attractionsNearby":["Assin Manso Ancestral Slave River Site","Cape Coast Castle","Elmina Castle (St George''s Castle)"],"imageCredit":"","sources":["https://visitghana.com/assin-manso-ancestral-slave-river-site/","https://www.graphic.com.gh/news/general-news/ghaa-news-emancipation-day-celebrations-kick-off-today.html","https://ghanaculture.gov.gh/central-region/"],"notes":""}'::jsonb),
  ('odwira-akuapem', 'Odwira Festival', 18, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'eastern', 'purification', 'Akropong-Akuapem (also Aburi, Larteh, Mamfe, Amanokrom)', 'Akuapem', 'September – October', 'A festival of spiritual purification in which the people are renewed and receive protection. It falls at harvest time, when gratitude is shown by "giving food to the ancestors".', 'https://commons.wikimedia.org/wiki/Special:FilePath/Obrafo_-_Traditional_Executioner_of_the_Akuapem_Traditional_Authority.jpg?width=1200', 'detailed', false, '{"alternateNames":["Akuapem Odwira"],"otherRegions":[],"traditionalArea":"Akuapem","usualDate":"","duration":"","historicalSignificance":"First celebrated in October 1826 under Nana Addo Dankwa I, the 19th Okuapehene, after the victory over the Asante army at the battle of Katamansu near Dodowa.","culturalSignificance":"Purification of the stools, reaffirmation of political loyalty and traditional allegiance. It is also kept in Jamestown, Accra, through Ga and Akuapem intermarriage.","activities":["Purification of the stools","Feeding of the ancestors","Durbar of chiefs","Drumming and dancing"],"attractionsNearby":["Aburi Botanical Gardens","Tetteh Quarshie Cocoa Farm, Mampong","Akonnedi Shrine, Larteh"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Obrafo_-_Traditional_Executioner_of_the_Akuapem_Traditional_Authority.jpg","sources":["https://en.wikipedia.org/wiki/Odwira_festival","https://ghanaculture.gov.gh/odwira-festival-september/","https://ghanaculture.gov.gh/eastern-region/"],"notes":"The NCC says the Odwira and Ohum festivals of the Akuapem ridge towns are held in turn from September to January."}'::jsonb),
  ('ohum', 'Ohum Festival', 19, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'eastern', 'harvest', 'Kyebi (Kibi) and Tafo', 'Akyem (also Akuapem)', 'June – July and September – October', 'Celebrated twice a year by all the towns of Akyem Abuakwa, with a grand durbar at Kyebi and Tafo, to mark the first yam harvest and ask for blessing in the coming year.', '', 'detailed', false, '{"alternateNames":["Ohumkan","Ohumkyire","Akyem Abuakwa Ohum"],"otherRegions":[],"traditionalArea":"Akyem Abuakwa","usualDate":"A Tuesday or Wednesday; Ohumkan in June/July, Ohumkyire in September/October","duration":"Two days","historicalSignificance":"It marks the anniversary of the Akyem nation and recalls the mythical appearance of Chief Okuru Banin I and his men from the River Birim and their migration to their present home.","culturalSignificance":"The Akyem give thanks for the River Birim and their land, remember the ancestors and pledge allegiance to the Okyenhene. A two-week ban on noise-making comes first.","activities":["Two-week ban on noise-making","Thanksgiving for the yam harvest","Pledge of allegiance to the Okyenhene","Grand durbar"],"attractionsNearby":["Atewa Range Forest Reserve","Ofori Panin Fie (Okyenhene''s palace), Kyebi"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Ohum_Festival","https://ghanaculture.gov.gh/aboakyer-festival1/","https://ghanaculture.gov.gh/eastern-region/","https://en.wikipedia.org/wiki/Ahumkan_Festival"],"notes":"Ohum-Kan and Ohum-Kyire are the two yearly parts of this one festival."}'::jsonb),
  ('dipo', 'Dipo', 20, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'eastern', 'initiation', 'Krobo Odumase and Somanya', 'Krobo (Dangme)', 'April', 'One of the best-known puberty rites in Ghana, performed for girls to usher them into womanhood. Initiates are adorned in beads and paraded through the community.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dipo_Rights_Procession_3.jpg?width=1200', 'detailed', false, '{"alternateNames":["Dipo puberty rites"],"otherRegions":["Greater Accra"],"traditionalArea":"Manya Krobo and Yilo Krobo","usualDate":"","duration":"","historicalSignificance":"Tradition says the rite was instituted by a priestess known as Klowεki.","culturalSignificance":"A symbol of Krobo heritage that marks readiness for adulthood and cleanses the girls spiritually. It is also an occasion to show the Krobo''s hand-made beads.","activities":["Shaving of the initiates'' heads and dressing in cloth","Parade of the initiates (dipo-yo) through the community","Ritual bath and libation by the chief priest","Display of beads"],"attractionsNearby":["Krobo Mountain","Cedi Beads Factory, Odumase Krobo","Boti Falls"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Dipo_Rights_Procession_3.jpg","sources":["https://en.wikipedia.org/wiki/Dipo","https://ghanaculture.gov.gh/dipo-puberty-rites-festival-february/","https://ghanaculture.gov.gh/eastern-region/"],"notes":"Wikipedia gives April; the NCC festival page gives February. It is a Krobo rite of the Eastern Region and is also performed in the Shai area, which is why your list had it under Greater Accra."}'::jsonb),
  ('ngmayem-manya-krobo', 'Ngmayem Festival (Manya Krobo)', 21, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'eastern', 'harvest', 'Odumase Krobo', 'Krobo (Dangme)', 'October', 'The annual harvest festival of the chiefs and people of Manya Krobo.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Manya Krobo","usualDate":"Usually between the last two Sundays of October","duration":"One week","historicalSignificance":"Established in 1944 under Nene Azu Mate Kole, Konor of Manya Krobo, replacing the older Yeliyem (\"eating of yam\") festival and reflecting the importance of millet to the Krobo.","culturalSignificance":"A festival of thanksgiving and communal identity, and a forum for leaders to address development.","activities":["Thanksgiving ceremonies","Traditional performances","Drumming and dancing","Durbar of chiefs"],"attractionsNearby":["Krobo Mountain","Akosombo Dam","Cedi Beads Factory, Odumase Krobo"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Ngmayem"],"notes":""}'::jsonb),
  ('kloyosikplem', 'Kloyosikplem Festival', 22, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'eastern', 'migration', 'Somanya', 'Krobo (Dangme)', 'November', 'Kloyosikplem means "descent from Krobo Mountain". It is celebrated by the chiefs and people of Yilo Krobo.', '', 'detailed', false, '{"alternateNames":["Kloyo Sikplemi"],"otherRegions":[],"traditionalArea":"Yilo Krobo","usualDate":"","duration":"","historicalSignificance":"Recalls the eviction of the Krobo from Krobo Mountain, their home and sacred place for centuries, by the British colonial government in 1892. The festival itself was instituted in 1992.","culturalSignificance":"Each year the people climb the mountain to pay homage to their ancestral home.","activities":["Expedition to the top of Krobo Mountain"],"attractionsNearby":["Krobo Mountain","Boti Falls","Umbrella Rock"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Kloyosikplem_festival","https://ghanaculture.gov.gh/kloyo-sikplemi-festival-november/","https://ghanaculture.gov.gh/eastern-region/"],"notes":""}'::jsonb),
  ('akwantukese', 'Akwantukese Festival', 23, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'eastern', 'migration', 'Koforidua', 'Asante (New Juaben)', 'November', 'Celebrated by the chiefs and people of the New Juaben Traditional Area to mark their great journey from Juaben in Ashanti.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"New Juaben","usualDate":"First week of November","duration":"","historicalSignificance":"Commemorates the migration of the Juabens and their allies, led by Asafo Adjei, to found New Juaben at Koforidua. Several Koforidua suburbs carry the names of Ashanti towns such as Oyoko, Asokore and Effiduase.","culturalSignificance":"A period for consecrating the black stools and invoking the blessing of the ancestors; a symbol of hope and unity.","activities":["Consecration of the black stools","Colourful durbar of chiefs"],"attractionsNearby":["Akaa Falls","Boti Falls","Koforidua bead market"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Akwantukese_Festival","https://ghanaculture.gov.gh/eastern-region/"],"notes":""}'::jsonb),
  ('kwahu-easter', 'Kwahu Easter', 24, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'eastern', 'heritage', 'Kwahu ridge towns (Atibie, Mpraeso, Obo, Abetifi)', 'Kwahu', 'March – April', 'The annual Easter celebration on the Kwahu hills. For the Kwahu it is a homecoming; for visitors it is one of Ghana''s biggest holiday parties.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Paragliding_at_Kwahu.jpg?width=1200', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Kwahu","usualDate":"Easter weekend","duration":"Three days","historicalSignificance":"A paragliding festival was added in 2005 at Atibie, launching from Odweanoma Mountain, and is described by the NCC as the first of its kind in sub-Saharan Africa.","culturalSignificance":"An annual homecoming for Kwahu citizens, combined with a community clean-up campaign.","activities":["Paragliding","Hiking","Carnivals and street jams","Live music performances","Community clean-up"],"attractionsNearby":["Odweanoma Mountain paragliding site","Oworobong Falls","Volta Lake at Adawso"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Paragliding_at_Kwahu.jpg","sources":["https://en.wikipedia.org/wiki/Kwahu_Easter","https://ghanaculture.gov.gh/eastern-region/"],"notes":""}'::jsonb),
  ('akwasidae', 'Akwasidae Festival', 25, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ashanti', 'ancestral', 'Kumasi (Manhyia Palace)', 'Asante', 'Recurring through the year', 'Part of the Adae cycle of the Akan calendar. Akwasidae falls on the final Sunday of each roughly six-week period and is celebrated by the Asante and their chiefs.', '', 'detailed', false, '{"alternateNames":["Akwasiadae"],"otherRegions":[],"traditionalArea":"Asante (Kumasi)","usualDate":"A Sunday once every six weeks (every 40 to 42 days)","duration":"One day","historicalSignificance":"The Adae days were fixed in ancient times and are not interchangeable.","culturalSignificance":"The rites honour personal and community ancestors. The last Akwasidae of the year coincides with Adae Kese.","activities":["Rites honouring the ancestors","Drumming, dancing and singing","Food offerings and donations"],"attractionsNearby":["Manhyia Palace Museum","Kejetia Market","Okomfo Anokye Sword Site","National Cultural Centre, Kumasi"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Akwasidae_Festival","https://en.wikipedia.org/wiki/Adae_Festival"],"notes":""}'::jsonb),
  ('awukudae', 'Awukudae Festival', 26, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ashanti', 'ancestral', 'Kumasi', 'Asante', 'Recurring through the year', 'The "Wednesday ceremony", the second of the two Adae days in each six-week cycle of the Akan calendar.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Asante (Kumasi)","usualDate":"A Wednesday every 40 to 42 days","duration":"One day","historicalSignificance":"","culturalSignificance":"An ancestral rite in which drumming seeks the protection of the ancestral deities for the ruling king and unites the people under him.","activities":["Drumming announcing the Adae on the eve and the morning","Ceremonies in the stool house"],"attractionsNearby":["Manhyia Palace Museum"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Awukudae_Festival","https://en.wikipedia.org/wiki/Adae_Festival"],"notes":""}'::jsonb),
  ('adae-kese', 'Adae Kese Festival', 27, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ashanti', 'ancestral', 'Kumasi (Manhyia Palace)', 'Asante', 'July – October', 'The "big Adae": an important but rare celebration that glorifies the achievements of the Asante kingdom and marks the turn of the Akan year.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Asante (Kumasi)","usualDate":"The ninth and final Adae of the Akan year","duration":"","historicalSignificance":"First celebrated to mark the statehood the Asante won at the Battle of Feyiase against Denkyira. Europeans called it the \"Yam custom\" because it coincides with the yam harvest.","culturalSignificance":"The Asantehene and his court display the full splendour of Asante culture. It is a day of rest, and the purification of Odwira is performed at the burial shrines of the ancestors.","activities":["Purification rites at the ancestral shrines","Display of royal regalia","Drumming and dances"],"attractionsNearby":["Manhyia Palace Museum","National Cultural Centre, Kumasi"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Adae_Kese_Festival","https://ghanaculture.gov.gh/ashanti-region/"],"notes":""}'::jsonb),
  ('papa-nantwi', 'Papa Nantwi Festival', 28, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ashanti', 'war-commemoration', 'Kumawu', 'Asante', 'March', 'An annual festival of the people of Kumawu in the Sekyere Kumawu District.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Kumawu","usualDate":"","duration":"","historicalSignificance":"Commemorates Nana Tweneboa Kodua I, who is said to have offered himself for sacrifice so that the Asante, under Osei Tutu I and Okomfo Anokye, could defeat their Denkyira overlords.","culturalSignificance":"Honours bravery and self-sacrifice; observed by Asante generally, with the events held at Kumawu.","activities":[],"attractionsNearby":["Bomfobiri Wildlife Sanctuary"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Papa_Nantwi_Festival"],"notes":"Not on your original list; added from Wikipedia to fill out the Ashanti Region."}'::jsonb),
  ('yaa-asantewaa', 'Yaa Asantewaa Festival', 29, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ashanti', 'heritage', 'Ejisu', 'Asante', 'August', 'Celebrated by the chiefs and people of the Ejisu Traditional Area in honour of Yaa Asantewaa.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Ejisu","usualDate":"","duration":"Nine days","historicalSignificance":"Honours Yaa Asantewaa''s actions in the War of the Golden Stool and remembers those exiled with her to the Seychelles, where she died on 17 October 1921.","culturalSignificance":"","activities":["Durbar of chiefs presided over by the paramount chief of Ejisu"],"attractionsNearby":["Yaa Asantewaa Museum, Ejisu","Ejisu-Besease Traditional Shrine"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Yaa_Asantewaa_Festival"],"notes":"Not on your original list; added from Wikipedia."}'::jsonb),
  ('kente-festival', 'Kente Festival', 30, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ashanti', 'heritage', 'Bonwire', 'Asante', 'January', 'Celebrated by the chiefs and people of Bonwire to promote the town''s Kente weaving.', 'https://commons.wikimedia.org/wiki/Special:FilePath/A_Kente_Festival.jpg?width=1200', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"","usualDate":"","duration":"","historicalSignificance":"Marks the origin of Kente cloth at Bonwire, said to have been invented there over 300 years ago.","culturalSignificance":"","activities":["Chiefs and townspeople wear Kente in many designs"],"attractionsNearby":["Bonwire Kente weaving village"],"imageCredit":"https://commons.wikimedia.org/wiki/File:A_Kente_Festival.jpg","sources":["https://en.wikipedia.org/wiki/Kente_Festival"],"notes":"Not on your original list. Wikipedia says some place it in July or August instead of January."}'::jsonb),
  ('kwafie', 'Kwafie Festival', 31, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bono', 'fire', 'Dormaa Ahenkro, Berekum, Nsoatre', 'Bono', 'November – January', 'A festival of remembrance and purification, best known for the large bonfire lit in the palace courtyard.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Dormaa, Berekum and Nsoatre","usualDate":"","duration":"About three days","historicalSignificance":"Commemorates the bringing of fire to the area, said to have been achieved by ancestors who migrated there long ago.","culturalSignificance":"The ancestors are honoured with libation and the stools are purified.","activities":["Evening torchlight procession from the palace to the stool house","Libation to the ancestors","Nkukuato, the \"laying of logs\" before the chief","Lighting of the fire and cooking of a ritual meal","Durbar of chiefs"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Kwafie_Festival"],"notes":"Your list also had Kwafie under Bono East and Ahafo; sources place it only at Dormaa, Berekum and Nsoatre in the Bono Region."}'::jsonb),
  ('munufie', 'Munufie Festival', 32, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bono', 'ancestral', 'Drobo, Japekrom, Suma', 'Bono (Gyaman)', 'September – October', 'Celebrated by the chiefs and people of Gyaman in the Jaman North and Jaman South districts.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Gyaman (Jaman)","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"","activities":["Durbar of chiefs","Drumming and dancing","Sharing of food and drink with visitors"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Munufie_Festival"],"notes":"Not on your original list. October in most of Gyaman; the Mpuasu-Japekrom and Abi traditional areas celebrate in September."}'::jsonb),
  ('sasabobirim', 'Sasabobirim Festival', 33, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bono', 'war-commemoration', 'Awuah-Domase, near Sunyani', 'Bono', 'November', 'Celebrated by the chiefs and people of the Awuah-Domase Traditional Area.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Awuah-Domase","usualDate":"","duration":"","historicalSignificance":"Held in remembrance of a chief who joined Yaa Asantewaa to fight the Europeans.","culturalSignificance":"","activities":["Durbar of chiefs","Drumming and dancing"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Sasabobirim_Festival"],"notes":"Not on your original list. Some sources give September."}'::jsonb),
  ('fofie-yam', 'Fofie Yam Festival', 34, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bono', 'harvest', 'Nchiraa, near Wenchi', 'Bono', 'October', 'A yam festival of the chiefs and people of Nchiraa.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"","activities":[],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Fofie_Yam_Festival"],"notes":"Not on your original list; one of the named yam festivals behind the \"Yam Festivals\" line for Bono."}'::jsonb),
  ('apoo', 'Apoo Festival', 35, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bono-east', 'purification', 'Techiman and Wenchi', 'Bono', 'March – April', 'A festival meant to ritually purify the people of social evils and to unite families. "Apoo" comes from the root "po", to reject.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":["Bono"],"traditionalArea":"Techiman and Wenchi","usualDate":"","duration":"One week","historicalSignificance":"Oral tradition traces it to the reign of Nana Kwakye Ameyaw, an authoritarian ruler. The people consulted the gods and were told to set aside days on which anyone could speak their mind, even to those in authority, without being held responsible.","culturalSignificance":"A period of social catharsis and reconciliation. Insults, proverbs, songs and histories of the Bono kingdom are exchanged in the Apoo procession.","activities":["Apoo procession with songs, proverbs and licensed insults","Recounting of Bono history","Traditional cultural performances"],"attractionsNearby":["Boabeng-Fiema Monkey Sanctuary","Kintampo Waterfalls","Tano Sacred Grove","Techiman Market"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Apoo_festival","https://ghanaculture.gov.gh/bono-east-region/","https://ghanaculture.gov.gh/bono-region/","https://ghanaculture.gov.gh/sample-october-festival-october/"],"notes":"Wikipedia gives March and April; the NCC festival page lists October."}'::jsonb),
  ('foyawoo', 'Foyawoo Festival', 36, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bono-east', 'harvest', 'Atebubu', 'Bono', 'October', 'A yam festival of the Atebubu, Kwafie and Amanten traditional areas.', '', 'basic', false, '{"alternateNames":["Foryaw Yam Festival"],"otherRegions":[],"traditionalArea":"Atebubu, Kwafie and Amanten","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"Prayers are offered to the gods and ancestors for peace, prosperity, good health and long life.","activities":["Chiefs carried in palanquins","Horn blowing, drumming and dancing","Sacrifices and prayers"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Foyawoo_Festival"],"notes":"Not on your original list. Some sources give September."}'::jsonb),
  ('nkyifie', 'Nkyifie Festival', 37, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bono-east', 'harvest', 'Prang', '', 'September', 'A yam festival of the chiefs and people of the Prang Traditional Area in the Pru West District.', '', 'basic', false, '{"alternateNames":["Nkyifie Yam Festival"],"otherRegions":[],"traditionalArea":"Prang","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"The people of Prang use it to review their performance over the year.","activities":["Durbar of chiefs","Drumming and dancing"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Nkyifie_Festival"],"notes":"Not on your original list. Sources variously give September, October, November or December."}'::jsonb),
  ('adekyem', 'Adekyem Festival', 38, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ahafo', 'heritage', 'Bechem', '', 'November – December', 'A festival of Bechem. The town''s name derives from "Adekyem", a place where items or gifts are shared.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"","usualDate":"","duration":"","historicalSignificance":"Recalls the historical role of Bechem as the place where booty won in the Asante wars was shared.","culturalSignificance":"","activities":[],"attractionsNearby":[],"imageCredit":"","sources":["https://ghanaculture.gov.gh/sample-december-festival-december/","https://ghanaculture.gov.gh/ahafo-region/"],"notes":"Your Ahafo list contained only general descriptions (yam, harvest and stool festivals). This is the one named Ahafo festival found in the NCC records."}'::jsonb),
  ('hogbetsotso', 'Hogbetsotso Festival', 39, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'migration', 'Anloga', 'Anlo Ewe', 'November', 'The "festival of exodus" of the Anlo, whose name means "coming from Hogbe (Notsie)". It is held at Anloga, the customary and ritual capital of the Anlo state.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hogb1.jpg?width=1200', 'detailed', false, '{"alternateNames":["Hogbetsotsoza"],"otherRegions":[],"traditionalArea":"Anlo","usualDate":"First Saturday in November","duration":"","historicalSignificance":"Commemorates the escape of the Anlo from Notsie, in present-day Togo, and the tyrannical king Togbe Agorkoli. The women softened one spot in the town''s earthen wall with waste water until it could be broken, and the people walked backwards to confuse their pursuers.","culturalSignificance":"A ceremony of purification of the traditional stool, bringing together the many Anlo towns.","activities":["Purification of the stool","Grand durbar of chiefs at Anloga","Drumming and dancing"],"attractionsNearby":["Keta Lagoon","Fort Prinzenstein, Keta","Woe Lighthouse","Keta beaches"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Hogb1.jpg","sources":["https://en.wikipedia.org/wiki/Hogbetsotso_festival","https://ghanaculture.gov.gh/sample-november-festival-november/","https://ghanaculture.gov.gh/volta-region/"],"notes":""}'::jsonb),
  ('asogli-te-za', 'Asogli Te Za', 40, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'harvest', 'Ho', 'Ewe (Asogli)', 'September', 'The yam festival of the Asogli people of Ho. "Te" is Ewe for yam, literally "it is swollen".', 'https://commons.wikimedia.org/wiki/Special:FilePath/Asogli_te_za_2018.jpg?width=1200', 'detailed', false, '{"alternateNames":["Asogli Yam Festival","Teduduza"],"otherRegions":[],"traditionalArea":"Asogli","usualDate":"","duration":"","historicalSignificance":"Oral history says a hunter found the yam in the forest during a famine, hid it in the soil and returned to find it had grown. The Ewe brought the celebration from Notsie in Togo. It lapsed for over a decade until Togbe Afede XIV revived it in 2004, and it was renamed Te Za on 8 May 2018.","culturalSignificance":"Teaches Asogli traditions to Ghanaians and visitors and unites chiefs from across the Volta Region, Ghana and Togo.","activities":["Traditional music and dance","Storytelling","Grand durbar"],"attractionsNearby":["Mount Adaklu","Kalakpa Resource Reserve","Volta Regional Museum, Ho"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Asogli_te_za_2018.jpg","sources":["https://en.wikipedia.org/wiki/Asogli_Te_Za","https://ghanaculture.gov.gh/volta-region/"],"notes":""}'::jsonb),
  ('sometutuza', 'Keta-Sometutuza', 41, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'migration', 'Agbozume', 'Ewe (Some)', 'November', 'Celebrated by the Some people of Agbozume, Denu and nearby communities in the Ketu South District.', '', 'detailed', false, '{"alternateNames":["Keta-Sometutu Festival"],"otherRegions":[],"traditionalArea":"Some","usualDate":"Third Saturday in November, two weeks after Hogbetsotso","duration":"","historicalSignificance":"Marks their migration from Keta in 1792–94, after the Keta–Anloga war.","culturalSignificance":"The chiefs pay homage to their paramount chief and renew their allegiance.","activities":["Traditional rites at Keta","Grand durbar at Agbozume","Display of Ewe Kente and other woven textiles"],"attractionsNearby":["Agbozume Kente market","Keta Lagoon"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Sometutuza"],"notes":""}'::jsonb),
  ('dzawuwu', 'Dzawuwu Festival', 42, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'ancestral', 'Dabala', 'Ewe (Agave)', 'February', 'A thanksgiving festival of the Agave. In Ewe, "Dza" is a food offering and "Wuwu" is sprinkling or ritual distribution.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Agave","usualDate":"","duration":"","historicalSignificance":"Traditional accounts trace it to the establishment of the Great Ivory Stool of Agave and the Gborble and Adzemu religious institutions, whose ritual cleansing and offerings became the festival.","culturalSignificance":"Combines thanksgiving, purification, remembrance of ancestors and the reaffirmation of traditional authority.","activities":["Ritual offering and sharing of sacred food among the Agave clans","Cleansing of sacred objects"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Dzawuwu_Festival"],"notes":""}'::jsonb),
  ('avenor-tutudoza', 'Avenor Tutudoza', 43, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'development', 'Akatsi', 'Ewe (Avenor)', 'November', 'A socio-cultural and economic development festival of the chiefs and people of Avenor in the Akatsi South Municipality.', '', 'basic', false, '{"alternateNames":["Avenortutuduza"],"otherRegions":[],"traditionalArea":"Avenor","usualDate":"","duration":"","historicalSignificance":"Introduced in 2018, when the earlier Avenor Hogbe Festival was rebranded.","culturalSignificance":"Celebrated to promote peace, harmony and development among the people of Avenor.","activities":["Agbadza dancing","Durbar of chiefs"],"attractionsNearby":[],"imageCredit":"","sources":["https://gna.org.gh/2024/11/chiefs-and-people-of-avenor-celebrate-avenortutudoza-2024/","https://ghanaculture.gov.gh/volta-region/"],"notes":""}'::jsonb),
  ('agbeliza', 'Agbeliza', 44, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'harvest', 'Akatsi, Avenorpedo, Avenorpeme', 'Ewe (Avenor)', 'August', 'The cassava festival of the Avenor people, showing more than 20 products made from the cassava plant.', '', 'basic', false, '{"alternateNames":["Cassava Festival"],"otherRegions":[],"traditionalArea":"Avenor","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"","activities":["Exhibition of cassava products such as agbelikaklo, yakayake and cassava cake","Agbadza dancing"],"attractionsNearby":[],"imageCredit":"","sources":["https://blastours.com/agbeliza-cassava-festival/","https://ghanaculture.gov.gh/volta-region/"],"notes":"Most sources give August; one gives the first week of November. The NCC also lists Agbeliza among the festivals of Battor."}'::jsonb),
  ('atsitoeza', 'Atsitoeza', 45, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'heritage', '', 'Ewe (Avenor)', '', '', '', 'name-only', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Avenor","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"","activities":[],"attractionsNearby":[],"imageCredit":"","sources":["https://ghanaculture.gov.gh/volta-region/"],"notes":"The NCC names it as a festival of the Avenor people but gives no date, history or activities."}'::jsonb),
  ('tortsogbeza', 'Tortsogbeza', 46, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'migration', 'Sokpoe (South Tongu District)', 'Ewe (Tongu)', 'April', 'The "river crossing" festival of the chiefs and people of Sokpoe.', '', 'basic', false, '{"alternateNames":["Sokpoe Tortzogbeza","River Crossing Festival"],"otherRegions":[],"traditionalArea":"Sokpoe","usualDate":"Around Easter","duration":"","historicalSignificance":"","culturalSignificance":"Held in gratitude to God and the forefathers. Libation is poured to cleanse the river before the crossing, in the belief that this keeps anyone, especially visitors, from drowning.","activities":["Libation to cleanse the river","Crossing of the river"],"attractionsNearby":["Lower Volta Bridge, Sogakope","Volta River"],"imageCredit":"","sources":["https://theheraldghana.com/abla-dzifa-gomashie-calls-for-support-for-sokpoe-tortzogbeza/","https://ghanaculture.gov.gh/volta-region/"],"notes":""}'::jsonb),
  ('battor-hogbeza', 'Battor Hogbeza', 47, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'migration', 'Battor', 'Ewe (Tongu)', 'December', 'The most widely observed festival of Battor.', '', 'basic', false, '{"alternateNames":["Battor Festival"],"otherRegions":[],"traditionalArea":"Battor","usualDate":"First week of December","duration":"","historicalSignificance":"Commemorates the escape of the forefathers from King Agorkoli at Notsie.","culturalSignificance":"Celebrated to unite the people of Battor.","activities":[],"attractionsNearby":["Volta River"],"imageCredit":"","sources":["https://ghanaculture.gov.gh/volta-region/","https://ntda.gov.gh/event/battor-festival/"],"notes":""}'::jsonb),
