  ('godigbeza', 'Godigbeza', 51, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'volta', 'migration', 'Aflao', 'Ewe (Aflao)', 'October', '"Godigbe" means liberation and "za" means festival. It is the festival of the people of Aflao.', '', 'basic', false, '{"alternateNames":["Godigbe Festival"],"otherRegions":[],"traditionalArea":"Aflao","usualDate":"","duration":"","historicalSignificance":"Remembers the mass departure of the people of Aflao from the rule of King Agorkoli at Notsie, in present-day Togo. The NCC says the festival was formally established by the paramount chief on 1 April 1967, having earlier been kept within homes and clan houses.","culturalSignificance":"","activities":["Grand durbar of chiefs with the people of Aflao"],"attractionsNearby":[],"imageCredit":"","sources":["https://ghanaculture.gov.gh/volta-region/","https://en.wikipedia.org/wiki/Godigbe_Festival"],"notes":"Not on your original list; added from the NCC Volta page."}'::jsonb),
  ('buem-lilu', 'Buem Lilu Festival', 52, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'harvest', 'Bodada (Jasikan District)', 'Buem', 'October', 'The annual yam festival of the Buem people, climaxing at Bodada, the Omanhene''s town.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Buem","usualDate":"Normally the second week of October; the Traditional Council fixes the date each year","duration":"About three weeks of events leading to the grand festival","historicalSignificance":"When the Buem settled under their leader King Aburam I, yam was the first crop they cultivated and became their staple, so a festival was held each year in its honour.","culturalSignificance":"Thanks the gods, honours the ancestors and the black stools, and reunites the Buem around King Aburam''s lesson of unity, symbolised by the broom.","activities":["Celebrations by individuals, shrines and each traditional ruler","Oath of allegiance by divisional chiefs to the Omanhene","Grand durbar on the Saturday","Cultural drumming and dancing"],"attractionsNearby":["Kute Waterfalls","Jasikan mountain cave"],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":""}'::jsonb),
  ('buyi-oka', 'Buyi Oka Festival', 53, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'development', 'New Baika', 'Buem', 'March', 'Celebrated only by the chiefs, elders and people of New Baika, to raise funds for the town''s development.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Buem","usualDate":"","duration":"Three days","historicalSignificance":"","culturalSignificance":"","activities":["Town cleaning","Health walk and health talk","Film show and games","Grand fund-raising durbar on the third day"],"attractionsNearby":[],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":""}'::jsonb),
  ('fussikor', 'Fussikor Festival', 54, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'migration', 'Bowiri Amanforo (Biakoye District)', 'Bowiri (Guan)', 'February – March', 'The traditional festival of the Bowiri people.', '', 'detailed', false, '{"alternateNames":["Fussikur","Fusikor"],"otherRegions":[],"traditionalArea":"Bowiri","usualDate":"","duration":"One week","historicalSignificance":"Commemorates the migration of the Bowiri from their ancestral home of Moree in the Central Region to Bowiri Amanforo.","culturalSignificance":"","activities":["Confinement of chiefs, queen mothers and priests","Day of wailing","Cleansing and purification of the black stools","Trip to the old settlement and shrines on Mount Fortorkpa","Grand durbar with Asafo drumming, dancing and musketry"],"attractionsNearby":["Otolili Odumase Oto Range, Bowiri Odumase","Kabo Forest Reserve"],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":"The NCC table groups Fusikor and Hyirehbo together and says timing varies from town to town."}'::jsonb),
  ('hyirebo', 'Hyirebo Afahye', 55, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'purification', 'Bowiri Amanforo (Biakoye District)', 'Bowiri (Guan)', 'April', 'The national festival of Bowiri, rounding off the traditional calendar.', '', 'detailed', false, '{"alternateNames":["Hyirehbo","Bowiriman Festival"],"otherRegions":[],"traditionalArea":"Bowiri","usualDate":"First week of April","duration":"One week","historicalSignificance":"Instituted as a proclamation of the new Bowiri state after the people migrated from Moree and founded \"Moree New Town\".","culturalSignificance":"A celebration of peace and the sanctification of the state, to ensure progress, unity and continuity.","activities":["Great Taboo Day with no farm work","Wailing day for departed heroes and loved ones","Feasting day","Dawn bath in the river and smearing of white clay","Processions to the durbar ground","Interdenominational thanksgiving service"],"attractionsNearby":[],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":""}'::jsonb),
  ('lissi', 'Lissi Festival', 56, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'harvest', 'Biakoye District', 'Bowiri (Guan)', 'August – September', 'Celebrated by the Bowiri people to mark a good harvest.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Bowiri","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"","activities":[],"attractionsNearby":[],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":""}'::jsonb),
  ('akwantutenten', 'Akwantutenten Festival', 57, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'migration', 'Worawora (Biakoye District)', 'Akan (Worawora)', 'September', 'An annual festival of the chiefs and people of Worawora, who are Akans.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Worawora","usualDate":"","duration":"","historicalSignificance":"Marks the exodus of the people of Worawora from Kuntunase in Ashanti to their present home.","culturalSignificance":"Stools and shrines are cleansed and pacified, with the people dressed in black.","activities":["Pilgrimage to the former settlements in the hills","Cleansing and pacification of stools and shrines","Grand durbar of chiefs"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Akwantutenten_Festival","https://ghanaculture.gov.gh/oti-region/"],"notes":"The NCC narrative and Wikipedia say September; the NCC table says October."}'::jsonb),
  ('akposo-ovazu', 'Akposo Ovazu', 58, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'harvest', 'Akposokubi and other Akposo towns (Biakoye District)', 'Akposo', 'October – December', 'The main festival of the Akposo: a harvest festival for fonio, locally called "ova".', '', 'basic', false, '{"alternateNames":["Yaa Asantewaa Ovazu"],"otherRegions":[],"traditionalArea":"Akposo","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"Thanks are given to Uwolowu, the Almighty God, and to the seven principal Akposo gods, of whom Wetu is the greatest.","activities":[],"attractionsNearby":[],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":"The NCC table lists this as \"Yaa Asantewaa Ovazu\" and gives its purpose as remembrance of the dead and past heroes."}'::jsonb),
  ('frikosuo', 'Frikooso Afahye', 59, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'war-commemoration', 'Tapa Abotoase (Biakoye District)', 'Akan (Tapa)', 'October', 'Celebrated by the Twi-speaking people of the Tapa Traditional Area with their allied neighbours.', '', 'detailed', false, '{"alternateNames":["Frikosuo"],"otherRegions":[],"traditionalArea":"Tapa","usualDate":"","duration":"","historicalSignificance":"Frikooso, a low hill 3 km north of Tapa Abotoase, was the battlefield where the people of Tapa, Worawora, Buem, Bowiri, Asato and their allies defeated an invading Asante force.","culturalSignificance":"Remembers the ancestors'' bravery and sacrifice in securing the land and its freedom.","activities":[],"attractionsNearby":["Volta Lake at Abotoase"],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":""}'::jsonb),
