  ('malade', 'Malade Festival', 76, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'harvest', 'Nkwanta South (Odomi, Keri, Kue)', 'Challa', 'December – January', 'A festival of the Challa people to praise their gods and thank them for a good harvest.', '', 'basic', false, '{"alternateNames":["Malader"],"otherRegions":[],"traditionalArea":"","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"Kept in individual homes. The aged and twins are cared for, and working tools such as hoes, cutlasses and guns are presented for blessing with promises for the new year.","activities":[],"attractionsNearby":["Kyabobo National Park","Breast Mountain, Kue"],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":"The NCC narrative says December/January; the NCC table says March/April."}'::jsonb),
  ('gidifon', 'Gidifon Festival', 77, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'harvest', 'Tutukpene (Nkwanta South)', 'Adele (Guan)', 'August – September', '"Gidifon" means new yam. It is the annual yam festival of the Adele people.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Adele","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"It is taboo for anyone in Adele land to eat the new yam until the rites honouring the Efuroko Stool and the ancestors are performed.","activities":["Rites to welcome the new yam","Ogyege, atrikpe and didutebye dances in the evening"],"attractionsNearby":["Kyabobo National Park","Shiare Waterfalls"],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":""}'::jsonb),
  ('gyogyibele', 'Gyogyibele Festival', 78, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'oti', 'harvest', 'Shiare and Akyode towns (Nkwanta South)', 'Akyode (Guan)', 'August – October', 'The annual yam festival of the Akyode people, both a religious and a social event.', '', 'detailed', false, '{"alternateNames":["Gyogyible"],"otherRegions":[],"traditionalArea":"Akyode","usualDate":"","duration":"","historicalSignificance":"The chiefs acknowledge the priest of the Brukum stool, which is believed to bless the yam before anyone may eat it.","culturalSignificance":"A renewal of the blessing of the stool and thanksgiving to the ancestors; also used to settle disputes and collect charity for the aged, widows and orphans.","activities":["Gekpaga, the day for cleansing the stool","Night-long dancing","Mashed yam (Gyofanya) carried to the durbar ground and offered to the ancestors","Oath-taking by divisional chiefs","Homage at the ancestral shrines"],"attractionsNearby":["Kyabobo National Park","Shiare Waterfalls"],"imageCredit":"","sources":["https://ghanaculture.gov.gh/oti-region/"],"notes":"The NCC narrative says August to October; the NCC table says October/November."}'::jsonb),
  ('damba', 'Damba Festival', 79, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'northern', 'religious', 'Yendi and Tamale (also Nalerigu, Damongo and Wa)', 'Dagomba (also Mamprusi, Gonja and Wala)', 'Lunar month of Damba (moves through the calendar year)', 'Described as the largest festival in Ghana, Damba is celebrated across the northern regions in the third month of the Dagomba lunar calendar, which corresponds to Rabia al-Awwal.', '', 'detailed', false, '{"alternateNames":["Damma (Mampruli)","Jingbenti (Waali)","Gonja Damba"],"otherRegions":["North East","Savannah","Upper East","Upper West"],"traditionalArea":"Dagbon (also Mamprugu, Gonja and Wala)","usualDate":"Somo Damba on the 11th day and Naa Damba on the 17th day of the month of Damba","duration":"","historicalSignificance":"First celebrated to mark the birth and naming of the Prophet Muhammad; over time its purpose became the glorification of heritage and chieftaincy. The Gonja of the Savannah Region have also adopted it.","culturalSignificance":"Celebrates the heritage, history and chieftaincy of Dagbon and the related kingdoms.","activities":["Announcement of the new month to the Yaa Naa","Somo Damba","Naa Damba (the King''s Damba)","Belkulsi, the farewell procession","Drumming, dancing and horse riding"],"attractionsNearby":["Gbewaa Palace, Yendi","Tamale Central Market","Mole National Park","Larabanga Mosque"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Damba_festival","https://ghanaculture.gov.gh/sample-august-festival-august/","https://ghanaculture.gov.gh/northern-region/"],"notes":"Because the date follows the lunar calendar it falls earlier each year; the NCC page lists July–August. This single entry covers the Damba celebrations you listed under five regions."}'::jsonb),
  ('bugum-chugu', 'Bugum Chugu', 80, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'northern', 'fire', 'Tamale and Yendi', 'Dagomba', 'Lunar month of Bugum (moves through the calendar year)', 'The fire festival, the first Dagomba festival of the year.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fire_festival3.jpg?width=1200', 'detailed', false, '{"alternateNames":["Buɣim Chuɣu","Fire Festival"],"otherRegions":["North East"],"traditionalArea":"Dagbon","usualDate":"Ninth day of Bugum Goli, the first month of the Dagomba lunar year","duration":"One night","historicalSignificance":"Remembers the lost son of an ancient king. The child fell asleep under a tree while playing and was forgotten; the king sent his warriors to search for him through the night with torches.","culturalSignificance":"One of the oldest Dagomba traditions, thought to predate the unification of Dagbon under Naa Gbewaa.","activities":["Night procession with flaming torches","Drumming and dancing"],"attractionsNearby":["Gbewaa Palace, Yendi","Tamale Central Market"],"imageCredit":"https://commons.wikimedia.org/wiki/File:Fire_festival3.jpg","sources":["https://en.wikipedia.org/wiki/Bugum_Chugu"],"notes":""}'::jsonb),
  ('kpini-chugu', 'Kpini Chugu', 81, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'northern', 'religious', '', 'Dagomba, Mamprusi and Nanumba', 'Fourth month after Damba (lunar calendar)', 'A minor festival whose name means "guinea fowl festival" in Dagbani.', '', 'basic', false, '{"alternateNames":["Guinea Fowl Festival"],"otherRegions":["North East"],"traditionalArea":"Dagbon, Mamprugu and Nanung","usualDate":"","duration":"","historicalSignificance":"Started under Naa Zangina, who is credited with bringing Islam to Dagbon. Folklore says a guinea fowl refused to show the thirsty Prophet where it had found water, so the bird is given a few lashes and slaughtered each year.","culturalSignificance":"","activities":["Ritual whipping and slaughter of a guinea fowl"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Kpini_Chugu"],"notes":"Not on your original list; added from Wikipedia."}'::jsonb),
  ('chimsi-chugu', 'Chimsi Chugu', 82, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'northern', 'religious', 'Tamale and Yendi', 'Dagomba', 'Lunar month of Chimsi (moves through the calendar year)', 'The Dagomba observance of Eid al-Adha, centred on sacrifice and prayer.', '', 'basic', false, '{"alternateNames":["Chimsi Festival","Eid al-Adha"],"otherRegions":[],"traditionalArea":"Dagbon","usualDate":"Tenth day of the month","duration":"","historicalSignificance":"","culturalSignificance":"","activities":["Drummers recite the drum history through the night of the ninth day","General prayers on the morning of the tenth day","Slaughter of animals and sharing of meat","Visiting and greeting in fine clothes"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Dagomba_people","https://www.firstofthemonth.org/images-from-the-chimsi-festival-eid-al-adha-in-tamale-in-the-1970s/"],"notes":""}'::jsonb),
  ('jintigi', 'Jintigi Festival', 83, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'savannah', 'fire', 'Damongo', 'Gonja', 'April', 'The fire festival of the Gonja Traditional Area, with Damongo, capital of Gonjaland, as its centre.', '', 'basic', false, '{"alternateNames":["Gonja Fire Festival"],"otherRegions":[],"traditionalArea":"Gonja","usualDate":"","duration":"","historicalSignificance":"Commemorates the search for the lost son of an ancient king.","culturalSignificance":"","activities":["Night procession with torches to the outskirts of towns and into the bush","Recitation of the Quran to forecast the coming year"],"attractionsNearby":["Mole National Park","Larabanga Mosque","Mystic Stone, Larabanga"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Jintigi_Festival"],"notes":"Your list also had Jintigi under North East; sources tie it to the Gonja of the Savannah Region. Like Bugum Chugu it follows the lunar calendar, so the April date given by Wikipedia will shift."}'::jsonb),
  ('fao', 'Fao Festival', 84, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-east', 'harvest', 'Navrongo', 'Kassena-Nankana', 'January', 'An annual harvest festival of the chiefs and people of Navrongo.', '', 'detailed', false, '{"alternateNames":["Foo"],"otherRegions":[],"traditionalArea":"Kassena-Nankana","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"Gives thanks to God, the gods and the ancestors for protection through the farming season and a good harvest, and reunites natives of the area to discuss development.","activities":["Durbar of chiefs","Traditional drumming and dancing","Cultural performances"],"attractionsNearby":["Navrongo Cathedral (Our Lady of Seven Sorrows)","Paga Crocodile Pond","Tono Dam"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Fao_festival","https://ghanaculture.gov.gh/sample-january-festival-february/"],"notes":""}'::jsonb),
  ('gologo', 'Gologo Festival', 85, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-east', 'harvest', 'Tengzug (Tong-Zuf), Gorogo and Yinduri', 'Talensi', 'March – April', 'A pre-harvest festival held before the sowing of the early millet.', '', 'detailed', false, '{"alternateNames":["Golib"],"otherRegions":[],"traditionalArea":"Talensi","usualDate":"March or early April, at the end of the dry season","duration":"Three days, in three different villages","historicalSignificance":"","culturalSignificance":"Reinforces belief in the Nnoo shrine, or Golib god, which regulates Talensi farming life. Sacrifices seek protection, plentiful rain and a good harvest. Noise-making and mourning are prohibited during the period.","activities":["Celebration at Gorogo, then Yinduri, then Tengzug","Libation at the Tengzug shrine","Dancing to new songs composed by the elders","Men dress in short knickers with a towel on the chest"],"attractionsNearby":["Tengzug Shrine","Tongo Hills"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Gologo_festival","https://ghanaculture.gov.gh/sample-march-festival-march/"],"notes":""}'::jsonb),
