  ('adaakoya', 'Adaakoya Festival', 88, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-east', 'harvest', 'Bolgatanga and Zuarungu', 'Frafra (Gurune), Talensi and Nabdam', 'January – February', 'The main harvest festival of the Frafra, Talensi and Nabdam communities. "Ndaa" means "during that time" and "Koya" means "I have farmed".', '', 'detailed', false, '{"alternateNames":["Ndaakoya"],"otherRegions":[],"traditionalArea":"Bolgatanga","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"An inherited ritual of thanksgiving to the gods for the harvest, rain and sunshine. It is celebrated each year by the Bolga Naaba, and every household is expected to mark it.","activities":["Durbar of chiefs","Sacrifices to the gods","Drumming, music and dancing"],"attractionsNearby":["Bolgatanga craft market","Sirigu Pottery and Art Village","Tongo Hills"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Adaakoya_Festival","https://en.wikipedia.org/wiki/Ndaakoya_festival"],"notes":""}'::jsonb),
