  ('kobine', 'Kobine Festival', 95, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-west', 'harvest', 'Lawra', 'Dagaaba', 'September – October', 'A traditional dance and festival unique to the Lawra area, celebrated to mark the end of a successful harvest.', '', 'detailed', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Lawra","usualDate":"","duration":"Four days","historicalSignificance":"","culturalSignificance":"Thanks the gods and ancestors for the harvest and is a celebration of family: those living away from Lawra return home.","activities":["Visits to family and friends on the first day","Procession of family heads with youths dressed as hunters and elephants","Speeches by dignitaries","Kobine dance competition to the kuor and dalar drums"],"attractionsNearby":["Black Volta at Lawra","Wechiau Community Hippo Sanctuary"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Kobine","https://ghanaculture.gov.gh/kobine-festival-september/","https://ghanaculture.gov.gh/upper-west-region/"],"notes":"The NCC Upper East page also lists Kobine, and your list had it under both regions; it belongs to Lawra in the Upper West."}'::jsonb),
  ('dumba', 'Dumba Festival', 96, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-west', 'religious', 'Wa', 'Wala', 'September – October', 'Celebrated by the chiefs and people of Wa, the seat of the Wala paramountcy.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Wala","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"An occasion to unite and renew commitment to Islam. The Wa Naa must jump over a tethered cow without touching it: success is said to prolong his life and show he is fit to rule, while failure is a bad omen.","activities":["The Wa Naa jumps over a tethered cow","Durbar of chiefs","Drumming and dancing"],"attractionsNearby":["Wa Naa''s Palace","Wechiau Community Hippo Sanctuary","Nakore Mosque"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Dumba_Festival"],"notes":"This is the Wala form of Damba (called Jingbenti in Waali), so the date follows the lunar calendar."}'::jsonb),
  ('kakube', 'Kakube Festival', 97, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-west', 'harvest', 'Nandom', 'Dagara', '', 'Celebrated by the people of Nandom to mark the end of the farming season.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"Nandom","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"Thanks the family gods for protection and guidance through the farming season and asks them to bless the soil; a time to renew relationships and show Nandom''s traditions.","activities":[],"attractionsNearby":["Nandom Basilica"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Kakube_festival"],"notes":"The source found does not state the month."}'::jsonb),
