  ('paragbeile', 'Paragbeile Festival', 99, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-west', 'harvest', 'Tumu', 'Sissala', 'January – February', 'Celebrated by the chiefs and people of Tumu.', '', 'basic', false, '{"alternateNames":["Paragbielle"],"otherRegions":[],"traditionalArea":"Tumu","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"","activities":["Durbar of chiefs","Drumming and dancing"],"attractionsNearby":["Gbele Resource Reserve"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Paragbeile_Festival"],"notes":""}'::jsonb),
  ('zumbenti', 'Zumbenti Festival', 100, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-west', 'purification', 'Kaleo (Nadowli District)', '', 'April', 'Celebrated by the chiefs and people of Kaleo.', '', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"Gives thanks to the ancestral gods, cleanses the land of evil spirits and reunites families; it is considered a favourable time to contract marriages.","activities":["Durbar of chiefs","Drumming and dancing"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Zumbenti_Festival"],"notes":"Not on your original list. Some sources give May."}'::jsonb),
  ('kalibi', 'Kalibi Festival', 101, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-west', 'war-commemoration', 'Sankana (Nadowli-Kaleo District)', '', 'April', 'Celebrated by the chiefs and people of Sankana.', 'https://commons.wikimedia.org/wiki/Special:FilePath/A_chief_at_Kalibi_festival.jpg?width=1200', 'basic', false, '{"alternateNames":[],"otherRegions":[],"traditionalArea":"","usualDate":"","duration":"","historicalSignificance":"Commemorates the victory of the local people over the slave raiders led by Babatu and Samori in 1896.","culturalSignificance":"The ancestors are asked for good health and prosperity.","activities":["Durbar of chiefs","Drumming and dancing"],"attractionsNearby":["Sankana Slave Caves"],"imageCredit":"https://commons.wikimedia.org/wiki/File:A_chief_at_Kalibi_festival.jpg","sources":["https://en.wikipedia.org/wiki/Kalibi_Festival"],"notes":"Not on your original list; added from Wikipedia."}'::jsonb),
  ('bob-ngo', 'Bob-Ngo Festival', 102, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-west', 'harvest', 'Jirapa', '', 'April', 'Celebrated by the chiefs and people of the Jirapa Traditional Area.', '', 'basic', false, '{"alternateNames":["Bongngo"],"otherRegions":[],"traditionalArea":"Jirapa","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"Lifts the taboo on harvesting the dawadawa crop, said to have been food for slaves and slave raiders in the past; without the festival the crop may not be harvested.","activities":["Durbar of chiefs","Drumming and dancing"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Bob-Ngo_Festival"],"notes":"Not on your original list; added from Wikipedia."}'::jsonb),
  ('sabre', 'Sabre Festival', 103, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'upper-west', 'heritage', 'Lawra', '', 'November', 'A dance festival of the Lawra Traditional Area.', '', 'basic', false, '{"alternateNames":["Sabre Dance Festival"],"otherRegions":[],"traditionalArea":"Lawra","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"","activities":["Durbar of chiefs","Drumming and dancing"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Sabre_Festival"],"notes":"Not on your original list; added from Wikipedia."}'::jsonb),
  ('kundum', 'Kundum Festival', 104, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'western', 'harvest', 'Sekondi, Axim and other Ahanta and Nzema towns', 'Ahanta and Nzema', 'July – August (Sekondi-Takoradi)', 'Both a harvest and a religious festival, celebrated to thank God for the abundance of food. It moves from town to town across the Ahanta and Nzema paramountcies.', '', 'detailed', false, '{"alternateNames":["Sekondi Kundum","Ahanta Kundum","Nzema Kundum"],"otherRegions":[],"traditionalArea":"Ahanta and Nzema","usualDate":"Each town picks the Sunday on which its own Kundum begins","duration":"Four weeks","historicalSignificance":"Folklore says a hunter, Akpoley, came upon dwarves dancing in a circle and brought the dance home. The NCC traces it to Aboadze near Agona Ahanta and the harvest god Kofi Kundum. The Dutch traveller Bosman recorded the festival in the 17th century.","culturalSignificance":"The ritual dance is associated with driving evil spirits from the towns, and the festival strengthens bonds among communities. For the first three weeks drumming and dancing take place only at night on the outskirts of town.","activities":["Kundum dance","Night drumming at the outskirts of town (Siedu)","Dance groups converge at Kundum Square, Sekondi"],"attractionsNearby":["Fort St Anthony, Axim","Fort Orange, Sekondi","Kundum Square (Komfo Ase), Sekondi","Busua Beach","Nzulezu stilt village"],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Kundum_Festival","https://ghanaculture.gov.gh/western-region/"],"notes":"Sekondi, Ahanta and Nzema Kundum are the same festival held at different times by each town, so they are one entry. Your list also placed Kundum under Central and Ashanti; no source supports a Kundum festival in Ashanti."}'::jsonb),
  ('alluolue', 'Alluolue Festival', 105, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'western-north', 'harvest', 'Sefwi Wiawso and Sefwi Bekwai', 'Sefwi', 'July', 'The yam festival of the chiefs and people of Sefwi Wiawso and Sefwi Bekwai.', '', 'basic', false, '{"alternateNames":["Eluo","Elluo","Sefwi Yam Festival"],"otherRegions":[],"traditionalArea":"Sefwi Wiawso and Sefwi Bekwai","usualDate":"","duration":"","historicalSignificance":"","culturalSignificance":"Brings people together to plan development and to strengthen bonds of unity and friendship.","activities":["Durbar of chiefs","Drumming and dancing","Sharing of food and drink with visitors"],"attractionsNearby":[],"imageCredit":"","sources":["https://en.wikipedia.org/wiki/Alluolue_Festival","https://ghanaculture.gov.gh/western-north-region/"],"notes":"Wikipedia gives July but adds that others place it in November/December."}'::jsonb)
insert into public.transport_options (id, name, position, created_at, updated_at, status, archived_at, type, description, image_url, details) values
  ('stc-bus', 'STC Bus (State Transport Corporation)', 0, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bus', 'The State Transport Corporation (STC) operates the most comfortable and reliable intercity bus service in Ghana. With air-conditioned coaches connecting major cities, STC is the preferred option for comfortable long-distance travel. Buses depart from designated STC terminals in major cities and reservations can be made in advance.', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800&q=80', '{"providers":["State Transport Corporation (STC)"],"routes":[{"from":"Accra","to":"Kumasi","estimatedDuration":"4.5 hours","estimatedCost":{"min":80,"max":120},"frequency":"Multiple daily departures","notes":"Departs from Accra STC Terminal, Tudu"},{"from":"Accra","to":"Cape Coast","estimatedDuration":"3 hours","estimatedCost":{"min":45,"max":65},"frequency":"Several daily departures"},{"from":"Accra","to":"Tamale","estimatedDuration":"9 hours","estimatedCost":{"min":120,"max":160},"frequency":"Daily overnight bus"},{"from":"Accra","to":"Takoradi","estimatedDuration":"4 hours","estimatedCost":{"min":60,"max":90},"frequency":"Daily"},{"from":"Kumasi","to":"Tamale","estimatedDuration":"6 hours","estimatedCost":{"min":90,"max":130},"frequency":"Daily"}],"safetyTips":["Book tickets in advance, especially during holidays and weekends","Arrive at the terminal at least 30 minutes early","Keep your ticket and luggage receipt safe","Do not leave valuables unattended on the bus","Use only official STC terminals and ticketing counters"],"pros":["Air-conditioned coaches","Fixed departures and arrival times","Advance booking available","Luggage storage","Reliable and reputable"],"cons":["More expensive than trotros","Limited to routes between major cities","Fixed schedules can be inflexible"],"bookingInfo":"Purchase tickets at STC terminals or call the STC booking line. Advance booking recommended for weekends and public holidays."}'::jsonb),
  ('vip-bus', 'VIP Jeoun Bus', 1, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bus', 'VIP Jeoun is a popular private intercity bus company offering comfortable, air-conditioned coaches between major Ghanaian cities at competitive prices. VIP buses often offer more frequent departures than STC and are a favourite among students, business travelers, and tourists. The "Executive Class" seats offer extra legroom and individual entertainment screens.', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800&q=80', '{"providers":["VIP Jeoun"],"routes":[{"from":"Accra","to":"Kumasi","estimatedDuration":"4.5 hours","estimatedCost":{"min":70,"max":110},"frequency":"Every 30 minutes, 5am–10pm"},{"from":"Accra","to":"Cape Coast","estimatedDuration":"3 hours","estimatedCost":{"min":40,"max":60},"frequency":"Frequent"},{"from":"Accra","to":"Ho","estimatedDuration":"3.5 hours","estimatedCost":{"min":55,"max":75},"frequency":"Daily"},{"from":"Accra","to":"Sunyani","estimatedDuration":"6 hours","estimatedCost":{"min":80,"max":110},"frequency":"Daily"}],"safetyTips":["Arrive early — popular routes fill up fast","Keep your belongings with you or under your seat","Confirm departure times at the terminal"],"pros":["Frequent departures","Affordable","Air-conditioned","Wide network","Executive class available"],"cons":["Can be crowded during peak times","Less punctual than STC on some routes"],"bookingInfo":"Purchase tickets at VIP terminals across major cities. No advance online booking — first come, first served."}'::jsonb),
  ('metro-mass-transit', 'Metro Mass Transit (MMT)', 2, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'bus', 'Metro Mass Transit is the part state-owned bus company set up in 2003 to give Ghanaians affordable public transport. Its orange buses run city routes, links to rural towns that other operators do not serve, and long-distance services between the regional capitals. The buses are plainer than the STC and VIP coaches and make more stops, but fares are usually among the lowest on a route.', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800&q=80', '{"providers":["Metro Mass Transit Company Limited"],"routes":[{"from":"Kumasi","to":"Tamale","estimatedDuration":"6–7 hours","estimatedCost":{"min":115,"max":115},"frequency":"Daily","notes":"Fare published by MMT for 2026"},{"from":"Accra","to":"Koforidua","estimatedDuration":"2 hours","estimatedCost":{"min":20,"max":40},"frequency":"Daily","notes":"Range reported across bus operators on this route in 2026"},{"from":"Accra","to":"Tamale","estimatedDuration":"10–12 hours","estimatedCost":{"min":180,"max":250},"frequency":"Daily","notes":"Range reported across bus operators on this route in 2026"},{"from":"Accra","to":"Bolgatanga","estimatedDuration":"13–15 hours","estimatedCost":{"min":200,"max":280},"frequency":"Daily","notes":"Range reported across bus operators on this route in 2026"}],"safetyTips":["Buy tickets only at MMT terminals or from the conductor on board","Arrive early: seats on long-distance buses are not always reserved","Keep valuables with you, not in the luggage hold","Carry water and snacks on long journeys; stops are limited"],"pros":["Among the cheapest fares between cities","Reaches rural towns other operators skip","Large buses with luggage space","Part state-owned and nationwide"],"cons":["Slower, with more stops than STC or VIP","Fewer comforts; not all buses are air-conditioned","Can be crowded","Timetables are less predictable"],"bookingInfo":"Tickets are sold at Metro Mass Transit terminals in the regional capitals, usually on the day of travel. Ask at the terminal for the day''s departures."}'::jsonb),
  ('trotro', 'Trotro (Shared Minibus)', 3, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'trotro', 'The trotro is the backbone of Ghana''s transport system — a shared minibus that operates on fixed urban and inter-urban routes. Inexpensive, ubiquitous, and deeply embedded in Ghanaian daily life, trotros serve almost every neighbourhood and town. They depart when full rather than on fixed schedules. Learning to use the trotro system is a rewarding way to experience authentic Ghanaian life and travel on a budget.', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800&q=80', '{"providers":[],"routes":[{"from":"Accra (Kaneshie)","to":"Cape Coast","estimatedDuration":"3.5 hours","estimatedCost":{"min":20,"max":35},"frequency":"Departs when full, throughout the day","notes":"Cheaper but less comfortable than STC/VIP"},{"from":"Accra (Kejetia)","to":"Kumasi (Kejetia)","estimatedDuration":"5 hours","estimatedCost":{"min":30,"max":50},"frequency":"Throughout the day"},{"from":"Accra City Centre","to":"Accra Suburbs","estimatedDuration":"20–60 mins","estimatedCost":{"min":3,"max":15},"frequency":"Very frequent"},{"from":"Kumasi","to":"Tamale","estimatedDuration":"7 hours","estimatedCost":{"min":60,"max":90},"frequency":"Daily"}],"safetyTips":["Confirm the destination with the \"mate\" (conductor) before boarding","Keep bags on your lap or in your sight","Avoid trotros packed far beyond capacity — this is unsafe","Use your phone or a map to track your route","Carry small change — exact fare is appreciated"],"pros":["Cheapest option for most journeys","Goes almost everywhere","Authentic local experience","No booking required"],"cons":["No fixed schedules (departs when full)","Can be overcrowded and hot","Not suitable for long distances with heavy luggage","Routes can be confusing for first-time visitors"]}'::jsonb),
  ('taxi', 'Metered & Shared Taxi', 4, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'taxi', 'Taxis are widely available in all Ghanaian cities and towns. They operate in two modes: chartered (private hire, you pay for the whole car) and shared (multiple passengers traveling in the same direction split the fare). Chartered taxis are ideal for direct, comfortable transport. Shared taxis are inexpensive for short urban trips. Fares should always be negotiated in advance — always agree on the price before entering a chartered taxi.', 'https://images.unsplash.com/photo-1511527661048-7fe73d85e9a4?w=800&q=80', '{"providers":[],"routes":[{"from":"Accra Airport","to":"Accra City Centre","estimatedDuration":"20–45 mins","estimatedCost":{"min":60,"max":120},"notes":"Negotiate fare at official taxi rank outside arrivals"},{"from":"Accra","to":"Cape Coast","estimatedDuration":"2.5 hours","estimatedCost":{"min":250,"max":450},"notes":"Chartered. Split with other travelers to reduce cost."},{"from":"Within Accra","to":"Any destination","estimatedDuration":"Varies","estimatedCost":{"min":20,"max":150},"notes":"Negotiate before entering. Shared taxi: ₵3-15"}],"safetyTips":["Always agree on the fare BEFORE getting in","Use only clearly marked taxis with visible plates","Prefer ride-hailing apps for greater safety and price transparency","Avoid entering taxis already occupied by strangers at night","Share taxis only in daylight with other passengers at official stops"],"pros":["Door-to-door convenience","Available everywhere","Shared taxis are very affordable","No schedule required"],"cons":["Fare negotiation can be stressful for visitors","Chartered taxis can be expensive","Quality varies widely"]}'::jsonb),
  ('ride-hailing', 'Uber, Bolt & Yango', 5, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'ride-hailing', 'Uber and Bolt operate in Accra and other major Ghanaian cities including Kumasi, Takoradi, and Tamale, and Yango operates in Accra and Kumasi. Ride-hailing apps offer the convenience of transparent pricing, cashless payment, driver tracking, and safety features — making them the preferred option for tourists visiting Ghana for the first time. Prices are generally reasonable by international standards.', 'https://images.unsplash.com/photo-1511527661048-7fe73d85e9a4?w=800&q=80', '{"providers":["Uber","Bolt","Yango"],"routes":[{"from":"Accra Airport","to":"Accra City Centre","estimatedDuration":"20–45 mins","estimatedCost":{"min":50,"max":100},"notes":"Much cheaper and safer than airport taxis"},{"from":"Within Accra","to":"Any Accra destination","estimatedDuration":"Varies","estimatedCost":{"min":25,"max":80},"notes":"Compare the apps before booking; Bolt and Yango are often cheaper than Uber"},{"from":"Within Kumasi","to":"Any Kumasi destination","estimatedDuration":"Varies","estimatedCost":{"min":20,"max":60}}],"safetyTips":["Confirm the driver''s name and car plate before entering","Share your ride details with someone you trust","Sit in the back seat","Keep the app open to track your route","Prefer cashless payment where possible"],"pros":["Transparent pricing","Cashless payment","Driver tracking","Rated drivers","Easy to book via app","Air-conditioned vehicles"],"cons":["Surge pricing during peak hours or events","Not available in smaller towns","Requires internet connection"],"bookingInfo":"Download the Uber, Bolt or Yango app. Create an account and add a payment method. Available 24/7 in Accra."}'::jsonb),
  ('domestic-flight', 'Domestic Flights', 6, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'domestic-flight', 'Domestic flights connect Accra (Kotoka International Airport) with Kumasi and Tamale, offering a fast alternative to the long road journeys to northern Ghana. Africa World Airlines (AWA) and PassionAir operate the main domestic routes. Flights to Tamale save approximately 8–10 hours compared to road travel and are ideal for travelers with limited time who want to visit Mole National Park.', 'https://images.unsplash.com/photo-1436491865332-7a61a109cc05?w=800&q=80', '{"providers":["Africa World Airlines (AWA)","PassionAir"],"routes":[{"from":"Accra (KIA)","to":"Kumasi (KMS)","estimatedDuration":"40 mins","estimatedCost":{"min":350,"max":600},"frequency":"Multiple daily flights","notes":"Book in advance for best prices"},{"from":"Accra (KIA)","to":"Tamale (TML)","estimatedDuration":"1 hour","estimatedCost":{"min":400,"max":800},"frequency":"Daily","notes":"Essential for Mole National Park visits"}],"safetyTips":["Book directly with airlines or authorised agents","Arrive at the airport at least 1.5 hours before departure","Carry your boarding pass (print or digital) and valid ID","Check baggage allowance in advance"],"pros":["Dramatically saves travel time to northern Ghana","Comfortable and reliable","Avoids long road journeys"],"cons":["Most expensive option","Limited destinations","Baggage restrictions apply"],"bookingInfo":"Book on Africa World Airlines (awagha.com) or PassionAir website. Also available on flight comparison apps."}'::jsonb),
  ('boat-ferry', 'Lake Volta Ferry', 7, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'boat', 'The Volta River Transport Company (VRTC) operates a passenger ferry service on Lake Volta between Akosombo and Yeji — one of the most unique and memorable journeys in Ghana. The multi-day ferry voyage takes passengers through the heart of the lake, stopping at small villages along the way. It is an adventurous, scenic, and deeply authentic Ghanaian experience. Shorter boat trips are also available at Ada Foah and other coastal/lake destinations.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800&q=80', '{"providers":["Volta River Transport Company (VRTC)"],"routes":[{"from":"Akosombo","to":"Yeji","estimatedDuration":"18–22 hours","estimatedCost":{"min":80,"max":250},"frequency":"Weekly departures","notes":"Cabin and deck class available. Bring food and water."},{"from":"Ada Foah","to":"Volta River","estimatedDuration":"2–4 hours","estimatedCost":{"min":100,"max":200},"notes":"Tourist river cruise — book through Ada Foah resorts"}],"safetyTips":["Always wear a life jacket provided on board","Bring your own food, water, and sunscreen for the Volta ferry","Check weather conditions before boat trips","Do not swim in Lake Volta — risk of bilharzia and crocodiles","Book the ferry cabin class for comfort on the overnight journey"],"pros":["Unique and unforgettable experience","Scenic journey through the lake","Affordable"],"cons":["Very slow — not practical for tight schedules","Basic facilities on the ferry","Irregular schedule"],"bookingInfo":"Purchase ferry tickets at the Akosombo boat dock. Contact VRTC for current schedules."}'::jsonb),
  ('shared-intercity-taxi', 'Long-Distance Shared Taxi', 8, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'shared-taxi', 'Long-distance shared taxis (often Toyota Camrys or similar saloon cars) operate between towns and cities, departing from specific lorry parks (bus stations) when the car is full. They are faster than trotros and less expensive than chartered taxis, offering a middle-ground option for intercity travel. Passengers pay per seat and can often negotiate the price for the entire car.', 'https://images.unsplash.com/photo-1511527661048-7fe73d85e9a4?w=800&q=80', '{"providers":[],"routes":[{"from":"Accra","to":"Cape Coast","estimatedDuration":"2.5–3 hours","estimatedCost":{"min":35,"max":60},"frequency":"Departs when full, throughout the day"},{"from":"Cape Coast","to":"Elmina","estimatedDuration":"20 mins","estimatedCost":{"min":8,"max":15},"frequency":"Very frequent"},{"from":"Kumasi","to":"Cape Coast","estimatedDuration":"4 hours","estimatedCost":{"min":60,"max":90},"frequency":"Throughout the day"}],"safetyTips":["Confirm the destination and fare before entering","Be cautious about overloading — 4 passengers max in a saloon car","Keep your luggage in the boot and take the key receipt","Departs from lorry parks — learn the relevant park for your route"],"pros":["Faster than trotro on intercity routes","More comfortable than trotro","Lower cost than chartered taxi or STC/VIP for some routes"],"cons":["Departs when full — can mean waiting","Driver quality varies","Less comfortable than VIP/STC buses for very long journeys"]}'::jsonb),
  ('okada-motorcycle', 'Okada (Motorcycle Taxi)', 9, '2026-01-01T00:00:00.000Z', '2026-01-01T00:00:00.000Z', 'published', null, 'taxi', 'Okada motorcycle taxis are widely used in smaller towns, rural areas, and northern Ghana for short distances where other transport options are limited. They are fast for navigating traffic and narrow roads, and very inexpensive. However, they carry significant safety risks and visitors should exercise caution. Note: Okada operations in Accra are restricted.', 'https://images.unsplash.com/photo-1547471080-7cc2caa01a7e?w=800&q=80', '{"providers":[],"routes":[{"from":"Tamale Centre","to":"Tamale Suburbs","estimatedDuration":"10–20 mins","estimatedCost":{"min":5,"max":20},"notes":"Very common in northern towns"},{"from":"Bolgatanga","to":"Paga","estimatedDuration":"45 mins","estimatedCost":{"min":30,"max":50},"notes":"Option when other transport is unavailable"}],"safetyTips":["Always insist on wearing a helmet — carry your own if possible","Avoid Okadas at night","Do not use for long distances or on major highways","Agree on fare before setting off","Hold on firmly and keep bags off the ground"],"pros":["Very fast in traffic","Reaches remote areas","Very cheap","Available almost everywhere in smaller towns"],"cons":["High safety risk","No helmet often provided","Banned in Accra and some other cities","Not suitable for luggage or long distances"]}'::jsonb)
